#!/usr/bin/env bash
# =============================================================================
#  Pingify - point-to-point tunnel manager for Iran <-> Kharej server pairs
#  https://github.com/GreatTeejay/Pingify
#
#  This file is generated by build.sh: it bundles the manager and the whole Go
#  core source, so a single file is everything either server needs.
#  Edit parts/*.sh and core/*.go, then run build.sh - never edit Pingify.sh.
# =============================================================================

PINGIFY_VERSION="3.10.0"
PINGIFY_REPO="GreatTeejay/Pingify"

CFG_DIR="/etc/pingify"
STATE_DIR="/var/lib/pingify"
SRC_DIR="/usr/local/src/pingify"
CORE_BIN="/usr/local/bin/pingify-core"
SELF_BIN="/usr/local/bin/pingify"
UNIT_DIR="/etc/systemd/system"
SYSCTL_FILE="/etc/sysctl.d/99-pingify.conf"
GO_MIN_MINOR=19          # the core needs Go 1.19 or newer
GO_FALLBACK="go1.22.12"  # used only when the version index is unreachable

# ---------------------------------------------------------------------------
# palette
# ---------------------------------------------------------------------------

if [ -t 1 ] && [ "${NO_COLOR:-}" = "" ] && [ "${TERM:-dumb}" != "dumb" ]; then
    C_OFF=$'\033[0m';   C_B=$'\033[1m';    C_DIM=$'\033[2m'
    C_RED=$'\033[31m';  C_GRN=$'\033[32m'; C_YEL=$'\033[33m'
    C_BLU=$'\033[34m';  C_MAG=$'\033[35m'; C_CYN=$'\033[36m'
    C_GRY=$'\033[90m'
else
    C_OFF=""; C_B=""; C_DIM=""; C_RED=""; C_GRN=""; C_YEL=""
    C_BLU=""; C_MAG=""; C_CYN=""; C_GRY=""
fi

# Box drawing degrades to ASCII on a console that is not talking UTF-8, so a
# bare serial session still renders something sane.
PINGIFY_UTF8=0
case "${LC_ALL:-${LC_CTYPE:-${LANG:-}}}" in
    *[Uu][Tt][Ff]*) PINGIFY_UTF8=1 ;;
esac

if [ "$PINGIFY_UTF8" = "1" ]; then
    BX_H='─'; BX_V='│'; BX_TL='╭'; BX_TR='╮'; BX_BL='╰'; BX_BR='╯'
    BX_DOT='·'; BX_ARR='▸'; BX_ON='●'; BX_OFF='○'
    MK_OK='✓'; MK_NO='✗'; MK_WARN='!'
else
    BX_H='-'; BX_V='|'; BX_TL='+'; BX_TR='+'; BX_BL='+'; BX_BR='+'
    BX_DOT='.'; BX_ARR='>'; BX_ON='*'; BX_OFF='o'
    MK_OK='+'; MK_NO='x'; MK_WARN='!'
fi

UI_W=64   # inner width of every panel, so the whole UI lines up

# ---------------------------------------------------------------------------
# drawing primitives
# ---------------------------------------------------------------------------

repeat() { local i n="$2" out=""; for ((i = 0; i < n; i++)); do out="$out$1"; done; printf '%s' "$out"; }

# Visible length, ignoring colour escapes - needed to pad a coloured string.
# Done with parameter expansion rather than sed: the live dashboard redraws
# every two seconds and a subprocess per cell adds up on a small VPS.
vislen() {
    local s="$1" out="" esc=$'\033['
    while [ "${s#*"$esc"}" != "$s" ]; do
        out="$out${s%%"$esc"*}"
        s="${s#*"$esc"}"
        s="${s#*m}"
    done
    out="$out$s"
    printf '%s' "${#out}"
}

pad_to() {
    local s="$1" w="$2" n; n="$(vislen "$s")"
    printf '%s' "$s"
    [ "$n" -lt "$w" ] && repeat ' ' $((w - n))
}

box_top() { printf '  %s%s%s%s%s\n' "$C_GRY" "$BX_TL" "$(repeat "$BX_H" "$UI_W")" "$BX_TR" "$C_OFF"; }
box_bot() { printf '  %s%s%s%s%s\n' "$C_GRY" "$BX_BL" "$(repeat "$BX_H" "$UI_W")" "$BX_BR" "$C_OFF"; }
box_row() { printf '  %s%s%s %s %s%s%s\n' "$C_GRY" "$BX_V" "$C_OFF" "$(pad_to "$1" $((UI_W - 2)))" "$C_GRY" "$BX_V" "$C_OFF"; }

say()  { printf '%s\n' "$*"; }
info() { printf '  %s%s%s %s\n' "$C_CYN" "$BX_ARR" "$C_OFF" "$*"; }
ok()   { printf '  %s%s%s %s\n' "$C_GRN" "$MK_OK" "$C_OFF" "$*"; }
warn() { printf '  %s%s%s %s\n' "$C_YEL" "$MK_WARN" "$C_OFF" "$*"; }
fail() { printf '  %s%s%s %s\n' "$C_RED" "$MK_NO" "$C_OFF" "$*"; }
dim()  { printf '    %s%s%s\n' "$C_DIM" "$*" "$C_OFF"; }
rule() { printf '  %s%s%s\n' "$C_GRY" "$(repeat "$BX_H" $((UI_W + 2)))" "$C_OFF"; }

# A section heading whose rule runs out to the panel width.
head2() {
    local t=" $1 " n; n="$(vislen "$t")"
    printf '\n  %s%s%s%s%s%s%s\n\n' \
        "$C_GRY" "$BX_H$BX_H" "$C_OFF$C_B" "$t" "$C_OFF$C_GRY" \
        "$(repeat "$BX_H" $((UI_W - n)))" "$C_OFF"
}

# item <key> <label> [hint]
#
# The label column grows if a label outruns it, so a long one can never end up
# glued to its hint.
item() {
    local w=28 n
    n="$(vislen "$2")"
    [ "$n" -ge "$w" ] && w=$((n + 2))
    if [ -n "${3:-}" ]; then
        printf '    %s%s%s  %s%s%s%s\n' \
            "$C_CYN$C_B" "$1" "$C_OFF" "$(pad_to "$2" "$w")" "$C_DIM" "$3" "$C_OFF"
    else
        printf '    %s%s%s  %s\n' "$C_CYN$C_B" "$1" "$C_OFF" "$2"
    fi
}

banner() {
    clear 2>/dev/null || true
    printf '\n'
    local l
    if [ "$PINGIFY_UTF8" = "1" ]; then
        for l in \
            '██████╗ ██╗███╗   ██╗ ██████╗ ██╗███████╗██╗   ██╗' \
            '██╔══██╗██║████╗  ██║██╔════╝ ██║██╔════╝╚██╗ ██╔╝' \
            '██████╔╝██║██╔██╗ ██║██║  ███╗██║█████╗   ╚████╔╝ ' \
            '██╔═══╝ ██║██║╚██╗██║██║   ██║██║██╔══╝    ╚██╔╝  ' \
            '██║     ██║██║ ╚████║╚██████╔╝██║██║        ██║   ' \
            '╚═╝     ╚═╝╚═╝  ╚═══╝ ╚═════╝ ╚═╝╚═╝        ╚═╝   '
        do
            printf '  %s%s%s\n' "$C_CYN" "$l" "$C_OFF"
        done
    else
        for l in \
            ' ___  _                 _   __       ' \
            '| _ \(_)_ _   __ _   (_) / _|_  _  ' \
            '|  _/| |  \ \ / _` |  | ||  _| || | ' \
            '|_|  |_|_||_|\__, |  |_||_|   \_, | ' \
            '             |___/           |__/  '
        do
            printf '  %s%s%s\n' "$C_CYN" "$l" "$C_OFF"
        done
    fi
    printf '  %s%sby Teejay%s   %sIran %s Kharej tunnel   %s   v%s%s\n\n' \
        "$C_CYN" "$C_DIM" "$C_OFF" "$C_DIM" "$BX_ARR" "$BX_DOT" "$PINGIFY_VERSION" "$C_OFF"
}

pause() { printf '\n'; read -rsp "  ${C_DIM}press enter${C_OFF}" _; printf '\n'; }

# ask VAR "prompt" ["default"]
ask() {
    local __var="$1" __prompt="$2" __def="${3:-}" __in=""
    if [ -n "$__def" ]; then
        read -rp "  ${C_CYN}${BX_ARR}${C_OFF} ${__prompt} ${C_DIM}[${__def}]${C_OFF}${C_B}:${C_OFF} " __in
        [ -z "$__in" ] && __in="$__def"
    else
        read -rp "  ${C_CYN}${BX_ARR}${C_OFF} ${__prompt}${C_B}:${C_OFF} " __in
    fi
    printf -v "$__var" '%s' "$__in"
}

confirm() {
    local reply=""
    read -rp "  ${C_YEL}?${C_OFF} $1 ${C_DIM}[y/N]${C_OFF}${C_B}:${C_OFF} " reply
    case "$reply" in [yY] | [yY][eE][sS]) return 0 ;; *) return 1 ;; esac
}

# A spinner for anything slow, so a download or a build never looks frozen.
spin() {
    local msg="$1"; shift
    if [ ! -t 1 ]; then "$@"; return $?; fi
    "$@" &
    local pid=$! i=0 frames='|/-\'
    while kill -0 "$pid" 2>/dev/null; do
        printf '\r  %s%s%s %s ' "$C_CYN" "${frames:i++%4:1}" "$C_OFF" "$msg"
        sleep 0.1
    done
    wait "$pid"
    local rc=$?
    printf '\r%s\r' "$(repeat ' ' $((${#msg} + 8)))"
    return $rc
}

# ---------------------------------------------------------------------------
# small utilities
# ---------------------------------------------------------------------------

require_root() {
    if [ "$(id -u)" != "0" ]; then
        fail "Pingify has to run as root. Try: sudo pingify"
        exit 1
    fi
}

have() { command -v "$1" >/dev/null 2>&1; }

# These configs are written by this script, one key per line, so a targeted
# sed is enough and Pingify stays free of a jq dependency.
json_str() { sed -n "s/^[[:space:]]*\"$2\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p" "$1" | head -n1; }
json_num() { sed -n "s/^[[:space:]]*\"$2\"[[:space:]]*:[[:space:]]*\([0-9][0-9]*\).*/\1/p" "$1" | head -n1; }

port_free() {
    local p="$1"
    if have ss; then
        ! ss -Hltn "sport = :$p" 2>/dev/null | grep -q . || return 1
    fi
    return 0
}

pick_free_port() {
    local p="${1:-9700}"
    while [ "$p" -lt 65535 ]; do
        if port_free "$p"; then printf '%s' "$p"; return 0; fi
        p=$((p + 1))
    done
    printf '%s' "$1"
}

public_ip() {
    local ip=""
    if have curl; then
        ip=$(curl -4 -fsS --max-time 5 https://api.ipify.org 2>/dev/null)
    fi
    if [ -z "$ip" ] && have ip; then
        ip=$(ip -4 route get 1.1.1.1 2>/dev/null | awk '{for(i=1;i<=NF;i++) if($i=="src"){print $(i+1); exit}}')
    fi
    printf '%s' "$ip"
}

tunnel_names() {
    [ -d "$CFG_DIR" ] || return 0
    local f
    for f in "$CFG_DIR"/*.json; do
        [ -e "$f" ] || continue
        basename "$f" .json
    done
}

tunnel_count() { tunnel_names | grep -c . ; }

svc_state() {
    if systemctl is-active --quiet "pingify@$1" 2>/dev/null; then printf 'active'
    elif systemctl is-enabled --quiet "pingify@$1" 2>/dev/null; then printf 'stopped'
    else printf 'disabled'; fi
}

# ---------------------------------------------------------------------------
# OS and toolchain
# ---------------------------------------------------------------------------

detect_os() {
    OS_ID="unknown"; OS_VER="0"; OS_PRETTY="unknown"
    if [ -r /etc/os-release ]; then
        # shellcheck disable=SC1091
        . /etc/os-release
        OS_ID="${ID:-unknown}"
        OS_VER="${VERSION_ID:-0}"
        OS_PRETTY="${PRETTY_NAME:-$OS_ID $OS_VER}"
    fi
    ARCH="$(uname -m)"
    case "$ARCH" in
        x86_64 | amd64)  GOARCH="amd64" ;;
        aarch64 | arm64) GOARCH="arm64" ;;
        armv7l | armv6l) GOARCH="armv6l" ;;
        *)               GOARCH="" ;;
    esac
}

apt_install() {
    export DEBIAN_FRONTEND=noninteractive
    if [ "${PINGIFY_APT_UPDATED:-}" != "1" ]; then
        apt-get update -qq >/dev/null 2>&1 || warn "apt-get update reported a problem, continuing"
        PINGIFY_APT_UPDATED=1
    fi
    apt-get install -y -qq "$@" >/dev/null 2>&1
}

ensure_deps() {
    local missing=()
    have curl   || missing+=(curl)
    have tar    || missing+=(tar)
    have ip     || missing+=(iproute2)
    have ss     || missing+=(iproute2)
    have base64 || missing+=(coreutils)
    if [ ${#missing[@]} -gt 0 ]; then
        if have apt-get; then
            spin "installing ${missing[*]}" apt_install "${missing[@]}" \
                || warn "some packages could not be installed"
        else
            warn "please install manually: ${missing[*]}"
        fi
    fi
    mkdir -p "$CFG_DIR" "$STATE_DIR"
    chmod 700 "$CFG_DIR"
}

# Prints the minor version of a Go toolchain, e.g. 22 for go1.22.2, or 0 when
# the binary is unusable or predates the 1.x scheme.
go_version_minor() {
    local v major rest minor
    v="$("$1" version 2>/dev/null | awk '{print $3}')"   # e.g. go1.22.2
    v="${v#go}"
    major="${v%%.*}"; rest="${v#*.}"; minor="${rest%%.*}"
    case "$major.$minor" in
        1.*[!0-9]* | 1.) printf '0'; return ;;
        1.*) printf '%s' "$minor" ;;
        *)   printf '0' ;;
    esac
}

find_go() {
    local cand
    for cand in "$(command -v go 2>/dev/null)" /usr/local/go/bin/go /usr/lib/go/bin/go; do
        [ -n "$cand" ] && [ -x "$cand" ] || continue
        if [ "$(go_version_minor "$cand")" -ge "$GO_MIN_MINOR" ] 2>/dev/null; then
            GO_BIN="$cand"; return 0
        fi
    done
    for cand in /usr/lib/go-*/bin/go; do
        [ -x "$cand" ] || continue
        if [ "$(go_version_minor "$cand")" -ge "$GO_MIN_MINOR" ] 2>/dev/null; then
            GO_BIN="$cand"; return 0
        fi
    done
    return 1
}

install_go_tarball() {
    [ -n "$GOARCH" ] || { fail "unsupported CPU architecture: $ARCH"; return 1; }
    local ver=""
    ver=$(curl -fsS --max-time 8 "https://go.dev/VERSION?m=text" 2>/dev/null | head -n1)
    case "$ver" in go1.*) ;; *) ver="$GO_FALLBACK" ;; esac
    info "downloading $ver for $GOARCH"
    if ! curl -fL --retry 2 --max-time 300 -o /tmp/pingify-go.tgz \
         "https://go.dev/dl/${ver}.linux-${GOARCH}.tar.gz"; then
        fail "could not download the Go toolchain"
        dim "this is only the fallback path - see Update Core for other options"
        return 1
    fi
    rm -rf /usr/local/go
    tar -C /usr/local -xzf /tmp/pingify-go.tgz || return 1
    rm -f /tmp/pingify-go.tgz
    [ -x /usr/local/go/bin/go ] || return 1
    GO_BIN="/usr/local/go/bin/go"
    return 0
}

ensure_go() {
    if find_go; then
        dim "using $("$GO_BIN" version)"
        return 0
    fi
    info "no suitable Go toolchain here (need 1.${GO_MIN_MINOR} or newer)"
    if have apt-get; then
        spin "installing golang-go from the distro" apt_install golang-go
        find_go && { dim "using $("$GO_BIN" version)"; return 0; }
    fi
    install_go_tarball || return 1
    dim "using $("$GO_BIN" version)"
    return 0
}

# ---------------------------------------------------------------------------
# the core
#
# Three ways to get it, tried in this order:
#   1. download the prebuilt binary for this CPU from GitHub Releases - the
#      normal path, a couple of seconds and no toolchain
#   2. compile the sources embedded in this script - needs Go but downloads
#      nothing, for a server that cannot reach the release files
#   3. import a binary you built elsewhere and copied across
# ---------------------------------------------------------------------------

release_base() { printf 'https://github.com/%s/releases/latest/download' "$PINGIFY_REPO"; }
core_asset()   { printf 'pingify-core-linux-%s' "$GOARCH"; }

core_version() {
    [ -x "$CORE_BIN" ] || { printf 'not installed'; return 1; }
    "$CORE_BIN" -version 2>/dev/null | awk '{print $2}' || printf 'unknown'
}

# Accept a candidate binary only once it has proved it runs on this machine.
adopt_core() {
    local tmp="$1"
    chmod +x "$tmp" 2>/dev/null
    if ! "$tmp" -version >/dev/null 2>&1; then
        fail "that binary does not run on this server (wrong architecture?)"
        rm -f "$tmp"
        return 1
    fi
    install -m 0755 "$tmp" "$CORE_BIN" || return 1
    rm -f "$tmp"
    ok "core ready: $("$CORE_BIN" -version)"
    return 0
}

download_core() {
    [ -n "$GOARCH" ] || { warn "no prebuilt core for $ARCH"; return 1; }
    have curl || return 1
    local base tmp="/tmp/pingify-core.dl" sums="/tmp/pingify-core.sums"
    base="$(release_base)"

    if ! spin "downloading the core for $GOARCH" \
         curl -fsSL --retry 2 --max-time 180 -o "$tmp" "$base/$(core_asset)"; then
        rm -f "$tmp"
        return 1
    fi

    # The checksum file is published alongside the binaries. A missing one is
    # not fatal, a wrong one is.
    if curl -fsSL --max-time 30 -o "$sums" "$base/SHA256SUMS" 2>/dev/null; then
        local want got
        want="$(awk -v a="$(core_asset)" '$2 ~ a {print $1; exit}' "$sums")"
        got="$(sha256sum "$tmp" | awk '{print $1}')"
        rm -f "$sums"
        if [ -n "$want" ] && [ "$want" != "$got" ]; then
            fail "checksum mismatch - refusing to install this download"
            rm -f "$tmp"
            return 1
        fi
        [ -n "$want" ] && dim "checksum verified"
    fi

    adopt_core "$tmp"
}

build_core() {
    ensure_go || return 1
    rm -rf "$SRC_DIR"
    mkdir -p "$SRC_DIR" || return 1
    write_core_sources "$SRC_DIR" || return 1
    printf 'module pingify\n\ngo 1.%s\n' "$GO_MIN_MINOR" > "$SRC_DIR/go.mod"

    local log="/tmp/pingify-build.log"
    go_build_now() {
        ( cd "$SRC_DIR" && \
          GOTOOLCHAIN=local GO111MODULE=on GOFLAGS=-mod=mod GOPROXY=off GOSUMDB=off \
          GOPATH="${GOPATH:-/tmp/pingify-gopath}" GOCACHE="${GOCACHE:-/tmp/pingify-gocache}" \
          CGO_ENABLED=0 "$GO_BIN" build -trimpath -ldflags "-s -w" \
          -o "$SRC_DIR/pingify-core" . ) >"$log" 2>&1
    }
    if ! spin "compiling the core (a minute or so on a small VPS)" go_build_now; then
        fail "the core did not compile"
        sed 's/^/      /' "$log" | tail -n 20
        return 1
    fi
    adopt_core "$SRC_DIR/pingify-core"
}

import_core_binary() {
    local src=""
    say ""
    dim "Point Pingify at a pingify-core binary you built or downloaded elsewhere."
    dim "A local path or an https URL both work."
    say ""
    ask src "path or URL"
    [ -n "$src" ] || return 1
    local tmp="/tmp/pingify-core.import"
    case "$src" in
        http://* | https://*)
            spin "downloading" curl -fsSL --max-time 300 -o "$tmp" "$src" \
                || { fail "download failed"; return 1; } ;;
        *)
            [ -f "$src" ] || { fail "no such file: $src"; return 1; }
            cp -f "$src" "$tmp" || return 1 ;;
    esac
    adopt_core "$tmp"
}

# install_core is the full ladder; ensure_core only runs it when needed.
install_core() {
    if download_core; then return 0; fi
    say ""
    warn "could not fetch the prebuilt core from GitHub"
    dim "compiling it here instead - this needs Go but downloads nothing"
    say ""
    build_core
}

ensure_core() {
    [ -x "$CORE_BIN" ] && return 0
    install_core
}

# ---------------------------------------------------------------------------
# systemd
# ---------------------------------------------------------------------------

write_units() {
    cat > "$UNIT_DIR/pingify@.service" <<'UNIT'
[Unit]
Description=Pingify tunnel %i
Documentation=https://github.com/GreatTeejay/Pingify
After=network-online.target
Wants=network-online.target
StartLimitIntervalSec=0

[Service]
Type=simple
ExecStart=/usr/local/bin/pingify-core -c /etc/pingify/%i.json
Restart=always
RestartSec=2
LimitNOFILE=1048576
TasksMax=infinity
NoNewPrivileges=yes
AmbientCapabilities=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
CapabilityBoundingSet=CAP_NET_ADMIN CAP_NET_BIND_SERVICE CAP_NET_RAW
ProtectHome=yes
ProtectSystem=full
StandardOutput=journal
StandardError=journal
SyslogIdentifier=pingify-%i

[Install]
WantedBy=multi-user.target
UNIT

    cat > "$UNIT_DIR/pingify-health.service" <<'UNIT'
[Unit]
Description=Pingify health check
ConditionPathExists=/usr/local/bin/pingify

[Service]
Type=oneshot
ExecStart=/usr/local/bin/pingify --health-check
SyslogIdentifier=pingify-health
UNIT

    cat > "$UNIT_DIR/pingify-health.timer" <<'UNIT'
[Unit]
Description=Pingify health check every 30s

[Timer]
OnBootSec=60s
OnUnitActiveSec=30s
AccuracySec=5s
Unit=pingify-health.service

[Install]
WantedBy=timers.target
UNIT

    cat > "$UNIT_DIR/pingify-recycle@.service" <<'UNIT'
[Unit]
Description=Pingify scheduled recycle of tunnel %i

[Service]
Type=oneshot
ExecStart=/bin/systemctl restart pingify@%i.service
SyslogIdentifier=pingify-recycle
UNIT

    systemctl daemon-reload
}

service_enable_start() {
    systemctl enable --now "pingify@$1" >/dev/null 2>&1
}

# ---------------------------------------------------------------------------
# tunnel configuration
# ---------------------------------------------------------------------------

# The T_* variables below describe one tunnel while the wizard runs.
cfg_reset() {
    T_NAME=""; T_ROLE=""; T_MODE="forward"; T_TRANSPORT="direct"
    T_LISTEN=""; T_CONNECT=""; T_PSK=""; T_PUBLIC_IP=""
    T_CARRIERS=4; T_WINDOW=512; T_KEEPALIVE=10
    T_FORWARDS=""; T_STATUS=""
    T_TUNIF="pfy0"; T_TUNLOCAL=""; T_TUNPEER=""; T_TUNMTU=1380
}

# cfg_render <role> <mode> <listen> <connect> <forwards-json> <status-addr>
# Prints one config document. Every key sits on its own line, which is what
# lets the manager read these files back with sed instead of a JSON parser.
cfg_render() {
    local role="$1" mode="$2" listen="$3" connect="$4" fwd="$5" status="$6"
    printf '{\n'
    printf '  "name": "%s",\n' "$T_NAME"
    printf '  "role": "%s",\n' "$role"
    printf '  "mode": "%s",\n' "$mode"
    printf '  "transport": "%s",\n' "$T_TRANSPORT"
    [ -n "$listen" ]  && printf '  "listen": "%s",\n' "$listen"
    [ -n "$connect" ] && printf '  "connect": "%s",\n' "$connect"
    printf '  "psk": "%s",\n' "$T_PSK"
    printf '  "carriers": %s,\n' "$T_CARRIERS"
    printf '  "window_kb": %s,\n' "$T_WINDOW"
    printf '  "keepalive_sec": %s,\n' "$T_KEEPALIVE"
    [ -n "$fwd" ] && printf '  "forwards": [%s],\n' "$fwd"
    if [ "$mode" = "tun" ]; then
        local lo="$T_TUNLOCAL" pe="$T_TUNPEER"
        if [ "$role" != "$T_ROLE" ]; then
            local pfx="${T_TUNLOCAL##*/}"
            [ "$pfx" = "$T_TUNLOCAL" ] && pfx=30
            lo="$T_TUNPEER/$pfx"
            pe="${T_TUNLOCAL%%/*}"
        fi
        printf '  "tun": { "name": "%s", "local": "%s", "peer": "%s", "mtu": %s },\n' \
               "$T_TUNIF" "$lo" "$pe" "$T_TUNMTU"
    fi
    printf '  "status_addr": "%s",\n' "$status"
    printf '  "log_level": "info"\n'
    printf '}\n'
}

cfg_save() {
    local file="$CFG_DIR/$T_NAME.json"
    cfg_render "$T_ROLE" "$T_MODE" "$T_LISTEN" "$T_CONNECT" "$T_FORWARDS" "$T_STATUS" > "$file"
    chmod 600 "$file"
    printf '%s' "$file"
}

# The peer document is this one mirrored: the sides swap, and whichever end
# dials becomes the end that listens.
cfg_peer_token() {
    local prole plisten pconnect pfwd
    if [ "$T_ROLE" = "server" ]; then prole="client"; else prole="server"; fi
    if [ -n "$T_CONNECT" ]; then
        plisten="0.0.0.0:${T_CONNECT##*:}"; pconnect=""
    else
        plisten=""; pconnect="${T_PUBLIC_IP}:${T_LISTEN##*:}"
    fi
    if [ "$prole" = "server" ]; then pfwd="$T_FORWARDS"; else pfwd=""; fi
    cfg_render "$prole" "$T_MODE" "$plisten" "$pconnect" "$pfwd" "$T_STATUS" | base64 | tr -d '\n'
}

parse_forwards() {
    local raw="$1" out="" item
    raw="${raw//,/ }"
    for item in $raw; do
        [ -n "$item" ] || continue
        [ -n "$out" ] && out="$out,"
        out="$out\"$item\""
    done
    printf '%s' "$out"
}

# Friendly names for the values stored in the config.
side_label()      { [ "$1" = "server" ] && printf 'IRAN' || printf 'KHAREJ'; }
mode_label()      { [ "$1" = "tun" ] && printf 'Full IP' || printf 'Ports'; }
transport_label() { case "$1" in direct) printf 'Direct' ;; *) printf '%s' "$1" ;; esac; }

# ---------------------------------------------------------------------------
# new tunnel
# ---------------------------------------------------------------------------

new_tunnel() {
    banner
    head2 "New Tunnel"
    ensure_core || { pause; return 1; }

    item 1 "Configure this server" "you will get a token for the other one"
    item 2 "Apply a token" "paste what the other server gave you"
    say ""
    local choice=""
    ask choice "select" "1"
    [ "$choice" = "2" ] && { import_tunnel; return; }

    cfg_reset

    # -- 1. identity -------------------------------------------------------
    head2 "1/7   Tunnel name"
    dim "used for the service name and the config file; letters and digits"
    say ""
    local suggested="pfy$(( $(tunnel_count) + 1 ))"
    while :; do
        ask T_NAME "name" "$suggested"
        case "$T_NAME" in
            "" | *[!a-zA-Z0-9_-]*)
                fail "letters, digits, dash and underscore only" ;;
            *)
                if [ -f "$CFG_DIR/$T_NAME.json" ]; then
                    fail "a tunnel named $T_NAME already exists"
                else
                    break
                fi ;;
        esac
    done

    # -- 2. which end is this ----------------------------------------------
    head2 "2/7   This server"
    item 1 "Iran" "clients connect to this server"
    item 2 "Kharej" "the panel and inbounds run on this server"
    say ""
    local side=""
    ask side "select" "1"
    [ "$side" = "2" ] && T_ROLE="client" || T_ROLE="server"

    # -- 3. link direction and endpoint ------------------------------------
    head2 "3/7   Link direction"
    dim "the tunnel is one link; only one end has to accept connections"
    say ""
    item 1 "Outbound" "this server connects to the other one"
    item 2 "Inbound" "the other one connects in; needs an open port"
    say ""
    local dir=""
    ask dir "select" "1"

    local tport=""
    say ""
    if [ "$dir" = "2" ]; then
        ask tport "listen port" "9443"
        T_LISTEN="0.0.0.0:$tport"
        port_free "$tport" || warn "port $tport is already in use on this server"
        T_PUBLIC_IP="$(public_ip)"
        ask T_PUBLIC_IP "public address of this server" "${T_PUBLIC_IP:-}"
    else
        local peer=""
        ask peer "address of the other server"
        [ -n "$peer" ] || { fail "an address is required"; pause; return 1; }
        ask tport "port on the other server" "9443"
        T_CONNECT="$peer:$tport"
    fi

    # -- 4. key ------------------------------------------------------------
    head2 "4/7   Shared key"
    dim "both servers authenticate with the same key; the token carries it"
    say ""
    item 1 "Generate" "recommended"
    item 2 "Enter an existing key" "if you already have one"
    say ""
    local kmode=""
    ask kmode "select" "1"
    say ""
    if [ "$kmode" = "2" ]; then
        ask T_PSK "key"
    else
        T_PSK="$("$CORE_BIN" -genpsk)"
        ok "generated"
    fi
    case "$T_PSK" in
        "" | *[!0-9a-fA-F]*) fail "a key is 64 hex characters"; pause; return 1 ;;
    esac

    # -- 5. transport ------------------------------------------------------
    head2 "5/7   Protocol"
    dim "how the link itself travels between the two servers"
    say ""
    item 1 "Direct" "encrypted stream, no wrapper - fastest"
    say ""
    dim "TLS and WebSocket are planned; Direct is the only one in this build"
    say ""
    local tr=""
    ask tr "select" "1"
    T_TRANSPORT="direct"

    # -- 6. payload --------------------------------------------------------
    head2 "6/7   What the tunnel carries"
    item 1 "Ports" "forward TCP and UDP ports - panels, inbounds"
    item 2 "Full IP" "a private layer-3 link between the two servers"
    say ""
    local m=""
    ask m "select" "1"
    say ""

    if [ "$m" = "2" ]; then
        T_MODE="tun"
        local sub=""
        ask sub "subnet index (0-63)" "1"
        case "$sub" in "" | *[!0-9]*) sub=1 ;; esac
        T_TUNIF="pfy${sub}"
        if [ "$T_ROLE" = "server" ]; then
            T_TUNLOCAL="10.71.${sub}.1/30"; T_TUNPEER="10.71.${sub}.2"
        else
            T_TUNLOCAL="10.71.${sub}.2/30"; T_TUNPEER="10.71.${sub}.1"
        fi
        ask T_TUNMTU "MTU" "1380"
        dim "this server takes ${T_TUNLOCAL}, the other one takes ${T_TUNPEER}"
    else
        T_MODE="forward"
        dim "port           same port on both servers"
        dim "443=8443       arrives on 443 here, reaches 8443 there"
        dim "udp:500        a UDP port"
        dim "8000-8010      a range"
        say ""
        local raw=""
        ask raw "ports on the Iran server, comma separated" "443"
        T_FORWARDS="$(parse_forwards "$raw")"
        [ -n "$T_FORWARDS" ] || { fail "at least one port is required"; pause; return 1; }
    fi

    # -- 7. performance ----------------------------------------------------
    head2 "7/7   Performance"
    dim "carriers are the parallel connections the link runs over; more of"
    dim "them absorb packet loss better, 4 to 8 suits most paths"
    say ""
    if confirm "change the defaults? (carriers ${T_CARRIERS}, window ${T_WINDOW} KB)"; then
        say ""
        ask T_CARRIERS "carriers" "$T_CARRIERS"
        ask T_WINDOW "window per stream in KB" "$T_WINDOW"
        ask T_KEEPALIVE "keepalive seconds" "$T_KEEPALIVE"
    fi
    case "$T_CARRIERS" in "" | *[!0-9]*) T_CARRIERS=4 ;; esac
    case "$T_WINDOW" in "" | *[!0-9]*) T_WINDOW=512 ;; esac
    case "$T_KEEPALIVE" in "" | *[!0-9]*) T_KEEPALIVE=10 ;; esac
    [ "$T_CARRIERS" -lt 1 ] && T_CARRIERS=1
    [ "$T_CARRIERS" -gt 64 ] && T_CARRIERS=64

    T_STATUS="127.0.0.1:$(pick_free_port 9700)"

    # -- review ------------------------------------------------------------
    banner
    head2 "Review"
    box_top
    box_row "$(pad_to "tunnel" 14)${C_B}${T_NAME}${C_OFF}"
    box_row "$(pad_to "this server" 14)$(side_label "$T_ROLE")"
    box_row "$(pad_to "link" 14)$([ -n "$T_CONNECT" ] && echo "outbound to $T_CONNECT" || echo "inbound on $T_LISTEN")"
    box_row "$(pad_to "protocol" 14)$(transport_label "$T_TRANSPORT")"
    box_row "$(pad_to "carries" 14)$(mode_label "$T_MODE")"
    if [ "$T_MODE" = "forward" ]; then
        box_row "$(pad_to "ports" 14)$(printf '%s' "$T_FORWARDS" | tr -d '"' | tr ',' ' ')"
    else
        box_row "$(pad_to "addresses" 14)${T_TUNLOCAL} ${BX_ARR} ${T_TUNPEER}"
    fi
    box_row "$(pad_to "carriers" 14)${T_CARRIERS}"
    box_bot
    say ""
    if ! confirm "create it?"; then
        warn "cancelled, nothing was written"
        pause
        return 1
    fi

    # -- write and start ---------------------------------------------------
    say ""
    local file; file="$(cfg_save)"
    if ! "$CORE_BIN" -c "$file" -check >/dev/null 2>&1; then
        fail "the core rejected this configuration"
        "$CORE_BIN" -c "$file" -check 2>&1 | sed 's/^/      /'
        rm -f "$file"
        pause; return 1
    fi

    write_units
    service_enable_start "$T_NAME"
    enable_watchdog quiet
    ok "$T_NAME is configured and running"

    # -- token -------------------------------------------------------------
    head2 "Token for the other server"
    dim "on the ${C_OFF}$( [ "$T_ROLE" = "server" ] && echo KHAREJ || echo IRAN )${C_DIM} server: New Tunnel ${BX_ARR} Apply a token"
    say ""
    rule
    printf '%s\n' "${C_YEL}$(cfg_peer_token)${C_OFF}"
    rule
    say ""
    warn "treat it like a password - it contains the shared key"
    say ""
    tunnel_status_block "$T_NAME"
    pause
}

# ---------------------------------------------------------------------------
# apply a token
# ---------------------------------------------------------------------------

import_tunnel() {
    head2 "Apply a token"
    dim "configure the other server first; it prints the token at the end"
    say ""
    local token=""
    ask token "token"
    [ -n "$token" ] || return 1

    local tmp="/tmp/pingify-import.json"
    if ! printf '%s' "$token" | base64 -d > "$tmp" 2>/dev/null; then
        fail "that is not a Pingify token"
        pause; return 1
    fi
    local name; name="$(json_str "$tmp" name)"
    if [ -z "$name" ]; then
        fail "the token is incomplete"
        rm -f "$tmp"; pause; return 1
    fi

    if [ -f "$CFG_DIR/$name.json" ]; then
        say ""
        warn "a tunnel named $name already exists on this server"
        confirm "replace it?" || { rm -f "$tmp"; return 1; }
        systemctl stop "pingify@$name" >/dev/null 2>&1
    fi

    # The status port chosen on the other server may be taken here.
    local sp; sp="$(json_str "$tmp" status_addr)"
    sed -i "s#\"status_addr\": \"[^\"]*\"#\"status_addr\": \"127.0.0.1:$(pick_free_port "${sp##*:}")\"#" "$tmp"

    # A token that dials needs the address of the server that issued it.
    local conn; conn="$(json_str "$tmp" connect)"
    if [ -n "$conn" ]; then
        case "${conn%%:*}" in
            "" | "0.0.0.0")
                say ""
                local ip=""
                ask ip "public address of the other server"
                sed -i "s#\"connect\": \"[^\"]*\"#\"connect\": \"$ip:${conn##*:}\"#" "$tmp" ;;
        esac
    fi

    install -m 600 "$tmp" "$CFG_DIR/$name.json"
    rm -f "$tmp"

    if ! "$CORE_BIN" -c "$CFG_DIR/$name.json" -check >/dev/null 2>&1; then
        say ""
        fail "the core rejected this configuration"
        "$CORE_BIN" -c "$CFG_DIR/$name.json" -check 2>&1 | sed 's/^/      /'
        rm -f "$CFG_DIR/$name.json"
        pause; return 1
    fi

    write_units
    service_enable_start "$name"
    enable_watchdog quiet
    say ""
    ok "$name is configured and running"
    say ""
    tunnel_status_block "$name"
    pause
}

# ---------------------------------------------------------------------------
# reading an existing tunnel back
# ---------------------------------------------------------------------------

cfg_load() {
    local f="$CFG_DIR/$1.json"
    [ -f "$f" ] || return 1
    cfg_reset
    T_NAME="$(json_str "$f" name)"
    T_ROLE="$(json_str "$f" role)"
    T_MODE="$(json_str "$f" mode)"
    T_TRANSPORT="$(json_str "$f" transport)"; : "${T_TRANSPORT:=direct}"
    T_LISTEN="$(json_str "$f" listen)"
    T_CONNECT="$(json_str "$f" connect)"
    T_PSK="$(json_str "$f" psk)"
    T_STATUS="$(json_str "$f" status_addr)"
    T_CARRIERS="$(json_num "$f" carriers)";      : "${T_CARRIERS:=4}"
    T_WINDOW="$(json_num "$f" window_kb)";       : "${T_WINDOW:=1024}"
    T_KEEPALIVE="$(json_num "$f" keepalive_sec)"; : "${T_KEEPALIVE:=10}"
    T_FORWARDS="$(sed -n 's/^[[:space:]]*"forwards"[[:space:]]*:[[:space:]]*\[\(.*\)\],*[[:space:]]*$/\1/p' "$f" | head -n1)"
    if [ "$T_MODE" = "tun" ]; then
        local tl; tl="$(grep -m1 '"tun"' "$f")"
        T_TUNIF="$(printf '%s' "$tl"    | sed -n 's/.*"name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')"
        T_TUNLOCAL="$(printf '%s' "$tl" | sed -n 's/.*"local"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')"
        T_TUNPEER="$(printf '%s' "$tl"  | sed -n 's/.*"peer"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p')"
        T_TUNMTU="$(printf '%s' "$tl"   | sed -n 's/.*"mtu"[[:space:]]*:[[:space:]]*\([0-9]*\).*/\1/p')"
        : "${T_TUNMTU:=1380}"
    fi
    return 0
}

# ---------------------------------------------------------------------------
# status rendering
# ---------------------------------------------------------------------------

tunnel_status_block() {
    local name="$1" f="$CFG_DIR/$1.json"
    [ -f "$f" ] || { fail "no such tunnel: $name"; return 1; }
    local addr; addr="$(json_str "$f" status_addr)"
    local state; state="$(svc_state "$name")"

    local colour="$C_RED"
    [ "$state" = "active" ] && colour="$C_GRN"
    printf '  %s%s%s  service %s%s%s\n' \
        "$C_B" "$name" "$C_OFF" "$colour" "$state" "$C_OFF"
    if [ -n "$addr" ] && [ -x "$CORE_BIN" ]; then
        "$CORE_BIN" -status "$addr" 2>/dev/null || true
    fi
}

# One line per tunnel, for the overview table.
tunnel_row() {
    local name="$1" f="$CFG_DIR/$1.json"
    local role mode peer addr state brief up total rtt streams
    role="$(json_str "$f" role)"
    mode="$(json_str "$f" mode)"
    peer="$(json_str "$f" connect)"
    [ -z "$peer" ] && peer="on ${C_OFF}$(json_str "$f" listen)"
    addr="$(json_str "$f" status_addr)"
    state="$(svc_state "$name")"

    up="-"; total="$(json_num "$f" carriers)"; rtt="-"; streams="-"
    if [ "$state" = "active" ] && [ -n "$addr" ] && [ -x "$CORE_BIN" ]; then
        brief="$("$CORE_BIN" -status "$addr" -brief 2>/dev/null)"
        if [ -n "$brief" ]; then
            # state up total rtt streams uptime
            set -- $brief
            up="$2"; streams="$5"
            # An unreachable endpoint reports zeroes; keep the configured
            # carrier count so the column still says what was asked for.
            [ "$3" != "0" ] && total="$3"
            if [ "$1" = "up" ]; then rtt="${4}ms"; else rtt="-"; fi
        fi
    fi

    # Green only when the tunnel is running *and* a carrier is actually up:
    # a running process with no peer is the failure people most need to see.
    local dot="$C_GRY$BX_OFF$C_OFF"
    case "$state" in
        active)
            if [ "$up" != "0" ] && [ "$up" != "-" ]; then dot="$C_GRN$BX_ON$C_OFF"
            else dot="$C_YEL$BX_ON$C_OFF"; fi ;;
        stopped)  dot="$C_YEL$BX_OFF$C_OFF" ;;
        disabled) dot="$C_GRY$BX_OFF$C_OFF" ;;
    esac

    printf '  %s %s %s %s %s %s%s%s\n' \
        "$dot" \
        "$(pad_to "${C_B}${name}${C_OFF}" 13)" \
        "$(pad_to "$role" 7)" \
        "$(pad_to "$mode" 8)" \
        "$(pad_to "$up/$total" 6)" \
        "$C_DIM" "$rtt" "$C_OFF"
}

list_tunnels() {
    local names; names="$(tunnel_names)"
    if [ -z "$names" ]; then
        dim "no tunnels configured yet - pick Config New Tunnel to make one"
        return 1
    fi
    printf '    %s%s %s %s %s %s%s\n' \
        "$C_DIM" \
        "$(pad_to "NAME" 13)" \
        "$(pad_to "ROLE" 7)" \
        "$(pad_to "MODE" 8)" \
        "$(pad_to "LINKS" 6)" \
        "RTT" "$C_OFF"
    local n
    for n in $names; do tunnel_row "$n"; done
    return 0
}

# ---------------------------------------------------------------------------
# manage tunnels
# ---------------------------------------------------------------------------

pick_tunnel() {
    local names; names="$(tunnel_names)"
    [ -n "$names" ] || { dim "no tunnels configured yet"; return 1; }
    local i=0 n
    say ""
    for n in $names; do
        i=$((i + 1))
        item "$i" "$n" "$(svc_state "$n")"
    done
    item 0 "Back"
    say ""
    local sel=""
    ask sel "select" "1"
    [ "$sel" = "0" ] && return 1
    case "$sel" in ''|*[!0-9]*) return 1 ;; esac
    PICKED="$(printf '%s\n' $names | sed -n "${sel}p")"
    [ -n "$PICKED" ]
}

manage_tunnels() {
    while :; do
        banner
        head2 "Manage Tunnels"
        list_tunnels || { pause; return; }
        if ! pick_tunnel; then return; fi
        tunnel_menu "$PICKED"
    done
}

tunnel_menu() {
    local name="$1"
    while :; do
        banner
        head2 "Tunnel: $name"
        tunnel_status_block "$name"
        rule
        item 1 "Restart"
        item 2 "Stop"
        item 3 "Start"
        item 4 "Live log"
        item 5 "Edit forwarded ports"
        item 6 "Performance settings"
        item 7 "Show the token again"
        item 8 "Scheduled restart"
        item 9 "Delete this tunnel"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) systemctl restart "pingify@$name"; ok "restarted"; sleep 1 ;;
            2) systemctl stop "pingify@$name"; ok "stopped"; sleep 1 ;;
            3) systemctl start "pingify@$name"; ok "started"; sleep 1 ;;
            4) say ""; dim "ctrl-c to stop following"; say ""
               journalctl -u "pingify@$name" -n 60 -f --no-pager || true ;;
            5) edit_forwards "$name" ;;
            6) edit_tuning "$name" ;;
            7) show_peer_token "$name" ;;
            8) recycle_menu "$name" ;;
            9) delete_tunnel "$name" && return ;;
            0|"") return ;;
        esac
    done
}

edit_forwards() {
    local name="$1" f="$CFG_DIR/$1.json"
    cfg_load "$name" || return 1
    if [ "$T_MODE" != "forward" ]; then
        warn "this is a full-IP tunnel; it has no port list"
        pause; return
    fi
    if [ "$T_ROLE" != "server" ]; then
        warn "ports are configured on the Iran side; this server is the Kharej end"
        pause; return
    fi
    say ""
    dim "current: $(printf '%s' "$T_FORWARDS" | tr -d '"')"
    say ""
    local raw=""
    ask raw "new port list (comma separated)"
    [ -n "$raw" ] || return
    local fwd; fwd="$(parse_forwards "$raw")"
    [ -n "$fwd" ] || { fail "nothing to set"; pause; return; }

    cp -f "$f" "$f.bak"
    if grep -q '"forwards"' "$f"; then
        sed -i "s#^\([[:space:]]*\"forwards\"[[:space:]]*:[[:space:]]*\).*#\1[$fwd],#" "$f"
    else
        sed -i "s#^\([[:space:]]*\"psk\".*\)#\1\n  \"forwards\": [$fwd],#" "$f"
    fi
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        rm -f "$f.bak"
        systemctl restart "pingify@$name"
        ok "ports updated and the tunnel restarted"
    else
        mv -f "$f.bak" "$f"
        fail "that port list was rejected, nothing changed"
    fi
    pause
}

edit_tuning() {
    local name="$1" f="$CFG_DIR/$1.json"
    cfg_load "$name" || return 1
    say ""
    local car win ka
    ask car "carriers" "$T_CARRIERS"
    ask win "window (KB)" "$T_WINDOW"
    ask ka  "keepalive (seconds)" "$T_KEEPALIVE"
    case "$car$win$ka" in *[!0-9]*) fail "numbers only"; pause; return ;; esac

    cp -f "$f" "$f.bak"
    sed -i "s#^\([[:space:]]*\"carriers\"[[:space:]]*:[[:space:]]*\).*#\1$car,#" "$f"
    sed -i "s#^\([[:space:]]*\"window_kb\"[[:space:]]*:[[:space:]]*\).*#\1$win,#" "$f"
    sed -i "s#^\([[:space:]]*\"keepalive_sec\"[[:space:]]*:[[:space:]]*\).*#\1$ka,#" "$f"
    if "$CORE_BIN" -c "$f" -check >/dev/null 2>&1; then
        rm -f "$f.bak"
        systemctl restart "pingify@$name"
        ok "updated and restarted"
        warn "set the same carrier count on the other server too"
    else
        mv -f "$f.bak" "$f"
        fail "rejected, nothing changed"
    fi
    pause
}

show_peer_token() {
    cfg_load "$1" || return 1
    if [ -z "$T_CONNECT" ]; then
        T_PUBLIC_IP="$(public_ip)"
        say ""
        ask T_PUBLIC_IP "public IP of THIS server" "${T_PUBLIC_IP:-}"
    fi
    say ""
    dim "paste this on the other server: Config New Tunnel -> option 2"
    say ""
    say "${C_YEL}$(cfg_peer_token)${C_OFF}"
    say ""
    pause
}

recycle_menu() {
    local name="$1"
    say ""
    if systemctl is-enabled --quiet "pingify-recycle@$name.timer" 2>/dev/null; then
        dim "a scheduled recycle is currently active"
        if confirm "turn it off?"; then
            systemctl disable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
            rm -f "$UNIT_DIR/pingify-recycle@$name.timer"
            systemctl daemon-reload
            ok "scheduled recycle removed"
        fi
        pause; return
    fi
    dim "Some Iranian ISPs quietly degrade long-lived connections. A periodic"
    dim "restart costs a second of downtime and clears that up."
    say ""
    local hours=""
    ask hours "restart every N hours (0 to cancel)" "6"
    case "$hours" in ''|*[!0-9]*|0) return ;; esac
    cat > "$UNIT_DIR/pingify-recycle@$name.timer" <<TIMER
[Unit]
Description=Pingify scheduled recycle of tunnel $name

[Timer]
OnBootSec=${hours}h
OnUnitActiveSec=${hours}h
RandomizedDelaySec=120
Unit=pingify-recycle@$name.service

[Install]
WantedBy=timers.target
TIMER
    systemctl daemon-reload
    systemctl enable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
    ok "the tunnel will recycle every ${hours}h"
    pause
}

delete_tunnel() {
    local name="$1"
    say ""
    confirm "really delete tunnel $name?" || return 1
    systemctl disable --now "pingify@$name" >/dev/null 2>&1
    systemctl disable --now "pingify-recycle@$name.timer" >/dev/null 2>&1
    rm -f "$UNIT_DIR/pingify-recycle@$name.timer"
    rm -f "$CFG_DIR/$name.json" "$CFG_DIR/$name.json.bak" "$STATE_DIR/$name.fail"
    systemctl daemon-reload
    ok "tunnel $name removed"
    sleep 1
    return 0
}

# ---------------------------------------------------------------------------
# health
#
# The core already reconnects a carrier on its own. This watchdog is the
# outer layer: it catches a wedged process, a tunnel that lost every carrier,
# and a service that failed to come back after a reboot.
# ---------------------------------------------------------------------------

HEALTH_STRIKES=3

run_health_check() {
    mkdir -p "$STATE_DIR"
    local n f addr fails
    for n in $(tunnel_names); do
        systemctl is-enabled --quiet "pingify@$n" 2>/dev/null || continue
        f="$CFG_DIR/$n.json"

        if ! systemctl is-active --quiet "pingify@$n"; then
            echo "pingify: $n is not running, starting it"
            systemctl restart "pingify@$n"
            echo 0 > "$STATE_DIR/$n.fail"
            continue
        fi

        addr="$(json_str "$f" status_addr)"
        if [ -z "$addr" ] || [ ! -x "$CORE_BIN" ]; then
            continue
        fi
        if "$CORE_BIN" -healthz "$addr" >/dev/null 2>&1; then
            echo 0 > "$STATE_DIR/$n.fail"
            continue
        fi

        fails="$(cat "$STATE_DIR/$n.fail" 2>/dev/null || echo 0)"
        case "$fails" in ''|*[!0-9]*) fails=0 ;; esac
        fails=$((fails + 1))
        echo "$fails" > "$STATE_DIR/$n.fail"
        echo "pingify: $n has no live carrier (strike $fails of $HEALTH_STRIKES)"
        if [ "$fails" -ge "$HEALTH_STRIKES" ]; then
            echo "pingify: restarting $n"
            systemctl restart "pingify@$n"
            echo 0 > "$STATE_DIR/$n.fail"
        fi
    done
}

enable_watchdog() {
    write_units
    systemctl enable --now pingify-health.timer >/dev/null 2>&1
    [ "${1:-}" = "quiet" ] || ok "watchdog enabled (checks every 30s)"
}

disable_watchdog() {
    systemctl disable --now pingify-health.timer >/dev/null 2>&1
    ok "watchdog disabled"
}

watchdog_state() {
    if systemctl is-enabled --quiet pingify-health.timer 2>/dev/null; then
        printf 'on'
    else
        printf 'off'
    fi
}

live_dashboard() {
    local key=""
    while :; do
        banner
        head2 "Live status"
        list_tunnels
        rule
        say "  ${C_DIM}watchdog: $(watchdog_state)   $(uptime | sed 's/^ *//')${C_OFF}"
        read -rsn1 -t 2 key
        case "$key" in q|Q) return ;; esac
    done
}

health_menu() {
    while :; do
        banner
        head2 "Health"
        list_tunnels
        rule
        item 1 "Live status dashboard"
        item 2 "Run a check now"
        item 3 "Enable the watchdog"
        item 4 "Disable the watchdog"
        item 5 "Recent health log"
        item 6 "Restart every tunnel"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) live_dashboard ;;
            2) say ""; run_health_check | sed 's/^/  /'; ok "check complete"; pause ;;
            3) enable_watchdog; pause ;;
            4) disable_watchdog; pause ;;
            5) say ""; journalctl -u pingify-health.service -n 40 --no-pager | sed 's/^/  /'; pause ;;
            6) local n
               for n in $(tunnel_names); do systemctl restart "pingify@$n"; ok "restarted $n"; done
               pause ;;
            0|"") return ;;
        esac
    done
}

# ---------------------------------------------------------------------------
# server and network tuning
#
# The defaults on a stock Ubuntu image are sized for a datacentre LAN. An
# Iran <-> Europe path has ~40-120 ms of RTT and real packet loss, so the
# kernel needs far more room in flight and a congestion control that does not
# read loss as congestion.
# ---------------------------------------------------------------------------

apply_tuning() {
    local want_forward="${1:-no}"
    say ""
    if [ -f "$SYSCTL_FILE" ]; then
        dim "replacing the previous Pingify tuning"
    else
        # Keep one copy of whatever the box looked like before we touched it.
        [ -f "$STATE_DIR/sysctl.pre" ] || sysctl -a 2>/dev/null > "$STATE_DIR/sysctl.pre"
    fi

    if ! lsmod 2>/dev/null | grep -q '^tcp_bbr'; then
        modprobe tcp_bbr 2>/dev/null || true
    fi
    if ! grep -q '^tcp_bbr$' /etc/modules-load.d/pingify.conf 2>/dev/null; then
        echo tcp_bbr > /etc/modules-load.d/pingify.conf
    fi

    local cc="cubic"
    if sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null | grep -qw bbr; then
        cc="bbr"
    else
        warn "this kernel has no BBR; staying on cubic"
    fi

    cat > "$SYSCTL_FILE" <<SYSCTL
# Written by Pingify $PINGIFY_VERSION. Delete this file and run
# "sysctl --system" to go back to the distribution defaults.

# --- congestion control and queueing ---
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = $cc

# --- room in flight: 64 MB covers a 200 ms / 2.5 Gbit path ---
net.core.rmem_max = 67108864
net.core.wmem_max = 67108864
net.core.rmem_default = 1048576
net.core.wmem_default = 1048576
net.ipv4.tcp_rmem = 4096 1048576 67108864
net.ipv4.tcp_wmem = 4096 1048576 67108864
net.ipv4.udp_rmem_min = 16384
net.ipv4.udp_wmem_min = 16384

# --- behave sensibly on a long, slightly lossy path ---
net.ipv4.tcp_mtu_probing = 1
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_no_metrics_save = 1
net.ipv4.tcp_notsent_lowat = 131072
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_window_scaling = 1
net.ipv4.tcp_sack = 1

# --- connection churn ---
net.core.somaxconn = 65535
net.core.netdev_max_backlog = 250000
net.ipv4.tcp_max_syn_backlog = 8192
net.ipv4.tcp_syncookies = 1
net.ipv4.tcp_fin_timeout = 15
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_keepalive_time = 300
net.ipv4.tcp_keepalive_intvl = 30
net.ipv4.tcp_keepalive_probes = 5
net.ipv4.ip_local_port_range = 10240 65535

# --- file descriptors ---
fs.file-max = 2097152
fs.nr_open = 2097152
SYSCTL

    if [ "$want_forward" = "yes" ]; then
        cat >> "$SYSCTL_FILE" <<'SYSCTL'

# --- routing, for full-IP tunnels ---
net.ipv4.ip_forward = 1
net.ipv6.conf.all.forwarding = 1
SYSCTL
    fi

    sysctl --system >/dev/null 2>&1
    ok "network tuning applied (congestion control: $cc, qdisc: fq)"

    if ! grep -q 'pingify' /etc/security/limits.d/99-pingify.conf 2>/dev/null; then
        cat > /etc/security/limits.d/99-pingify.conf <<'LIMITS'
# Pingify
*   soft  nofile  1048576
*   hard  nofile  1048576
root soft nofile  1048576
root hard nofile  1048576
LIMITS
        ok "file descriptor limits raised (log out and back in for shells)"
    fi
}

revert_tuning() {
    rm -f "$SYSCTL_FILE" /etc/security/limits.d/99-pingify.conf /etc/modules-load.d/pingify.conf
    sysctl --system >/dev/null 2>&1
    ok "Pingify tuning removed; the distribution defaults are back"
    dim "a reboot makes absolutely sure nothing is left over"
}

show_net_settings() {
    say ""
    printf '  %-34s %s\n' "congestion control" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"
    printf '  %-34s %s\n' "available" "$(sysctl -n net.ipv4.tcp_available_congestion_control 2>/dev/null)"
    printf '  %-34s %s\n' "default qdisc" "$(sysctl -n net.core.default_qdisc 2>/dev/null)"
    printf '  %-34s %s\n' "rmem_max" "$(sysctl -n net.core.rmem_max 2>/dev/null)"
    printf '  %-34s %s\n' "wmem_max" "$(sysctl -n net.core.wmem_max 2>/dev/null)"
    printf '  %-34s %s\n' "tcp_rmem" "$(sysctl -n net.ipv4.tcp_rmem 2>/dev/null)"
    printf '  %-34s %s\n' "tcp_wmem" "$(sysctl -n net.ipv4.tcp_wmem 2>/dev/null)"
    printf '  %-34s %s\n' "mtu probing" "$(sysctl -n net.ipv4.tcp_mtu_probing 2>/dev/null)"
    printf '  %-34s %s\n' "ip_forward" "$(sysctl -n net.ipv4.ip_forward 2>/dev/null)"
    printf '  %-34s %s\n' "open file limit" "$(ulimit -n)"
    printf '  %-34s %s\n' "Pingify tuning file" "$([ -f "$SYSCTL_FILE" ] && echo present || echo absent)"
    say ""
}

manage_swap() {
    say ""
    local cur; cur="$(free -m | awk '/^Swap:/{print $2}')"
    dim "current swap: ${cur:-0} MB"
    if [ "${cur:-0}" -gt 0 ] 2>/dev/null; then
        if confirm "remove the existing Pingify swap file?"; then
            swapoff /swapfile 2>/dev/null || true
            sed -i '\#^/swapfile #d' /etc/fstab
            rm -f /swapfile
            ok "swap file removed"
            pause; return
        fi
    fi
    local mb=""
    ask mb "swap size in MB (0 to cancel)" "1024"
    case "$mb" in ''|*[!0-9]*|0) return ;; esac
    swapoff /swapfile 2>/dev/null || true
    rm -f /swapfile
    info "creating a ${mb}MB swap file"
    if ! fallocate -l "${mb}M" /swapfile 2>/dev/null; then
        dd if=/dev/zero of=/swapfile bs=1M count="$mb" status=none || { fail "could not create it"; pause; return; }
    fi
    chmod 600 /swapfile
    mkswap /swapfile >/dev/null 2>&1
    swapon /swapfile || { fail "swapon failed"; pause; return; }
    grep -q '^/swapfile ' /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab
    sysctl -w vm.swappiness=10 >/dev/null 2>&1
    ok "swap ready"
    pause
}

optimize_menu() {
    while :; do
        banner
        head2 "Optimize"
        item 1 "Apply network tuning" "(BBR + fq + high-BDP buffers)"
        item 2 "Apply network tuning" "+ enable IP forwarding (full-IP tunnels)"
        item 3 "Show the current settings"
        item 4 "Swap file"
        item 5 "Sync the clock" "(the handshake rejects a skewed clock)"
        item 6 "Revert every change Pingify made"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) apply_tuning no; pause ;;
            2) apply_tuning yes; pause ;;
            3) show_net_settings; pause ;;
            4) manage_swap ;;
            5) sync_clock; pause ;;
            6) say ""; confirm "revert the sysctl and limits changes?" && revert_tuning; pause ;;
            0|"") return ;;
        esac
    done
}

sync_clock() {
    say ""
    info "current time: $(date -u '+%Y-%m-%d %H:%M:%S UTC')"
    if have timedatectl; then
        timedatectl set-ntp true 2>/dev/null && ok "NTP synchronisation enabled"
        timedatectl status 2>/dev/null | sed 's/^/  /'
    else
        warn "timedatectl is missing; install systemd-timesyncd or chrony"
    fi
    dim "Pingify rejects a handshake more than 3 minutes out, so both servers"
    dim "must agree on the time."
}

# ---------------------------------------------------------------------------
# update / remove
# ---------------------------------------------------------------------------

RAW_BASE="https://raw.githubusercontent.com/GreatTeejay/Pingify/main"

update_menu() {
    while :; do
        banner
        head2 "Core"
        printf '  %-22s %s\n' "core" "$(core_version)"
        printf '  %-22s %s\n' "manager" "$PINGIFY_VERSION"
        printf '  %-22s %s\n' "Go toolchain" "$(find_go >/dev/null 2>&1 && "$GO_BIN" version || echo 'not installed')"
        rule
        item 1 "Download the latest core" "prebuilt, from GitHub Releases"
        item 2 "Compile the core here" "from the sources inside this script"
        item 3 "Import a core binary" "path or URL"
        item 4 "Export this core binary" "to copy to the peer"
        item 5 "Update Pingify itself" "fetch the newest manager script"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) say ""; if download_core; then restart_all "the core was updated"; fi; pause ;;
            2) say ""; if build_core; then restart_all "the core was rebuilt"; fi; pause ;;
            3) say ""; if import_core_binary; then restart_all "the core was replaced"; fi; pause ;;
            4) export_core; pause ;;
            5) self_update; pause ;;
            0|"") return ;;
        esac
    done
}

restart_all() {
    local n any=0
    for n in $(tunnel_names); do any=1; systemctl restart "pingify@$n"; done
    [ "$any" = "1" ] && ok "$1; every tunnel was restarted" || ok "$1"
}

self_update() {
    say ""
    have curl || { fail "curl is needed for this"; return 1; }
    info "fetching the latest Pingify from GitHub"
    local tmp="/tmp/pingify.new"
    if ! curl -fsSL --max-time 60 "$RAW_BASE/Pingify.sh" -o "$tmp"; then
        fail "could not reach GitHub"
        dim "on an Iranian server this often fails; update from the Kharej box"
        dim "and copy the file across instead."
        return 1
    fi
    if ! bash -n "$tmp" 2>/dev/null; then
        fail "the downloaded file is not valid, refusing to install it"
        rm -f "$tmp"; return 1
    fi
    local newver; newver="$(grep -m1 '^PINGIFY_VERSION=' "$tmp" | cut -d'"' -f2)"
    install -m 0755 "$tmp" "$SELF_BIN"
    rm -f "$tmp"
    ok "Pingify updated to ${newver:-unknown}"
    dim "run 'pingify' again to pick up the new version"
}

export_core() {
    say ""
    [ -x "$CORE_BIN" ] || { fail "no core is installed here"; return 1; }
    local dest="/root/pingify-core-$(uname -m)"
    cp -f "$CORE_BIN" "$dest"
    ok "copied to $dest"
    dim "Move it to the other server and use Update Core -> 3 there."
    dim "Example, run this on the other server:"
    say ""
    say "    ${C_DIM}scp root@$(public_ip):$dest /root/pingify-core${C_OFF}"
}

remove_menu() {
    banner
    head2 "Remove"
    item 1 "Remove the core only" "tunnels and configs stay"
    item 2 "Remove every tunnel" "configs and services, core stays"
    item 3 "Full uninstall" "everything Pingify ever wrote"
    item 0 "Back"
    say ""
    local c=""
    ask c "select"
    case "$c" in
        1)  say ""
            confirm "remove $CORE_BIN?" || return
            local n
            for n in $(tunnel_names); do systemctl stop "pingify@$n" >/dev/null 2>&1; done
            rm -f "$CORE_BIN"
            rm -rf "$SRC_DIR"
            ok "core removed; rebuild it from Update Core when you need it"
            pause ;;
        2)  say ""
            confirm "delete every tunnel on this server?" || return
            local n
            for n in $(tunnel_names); do
                systemctl disable --now "pingify@$n" >/dev/null 2>&1
                systemctl disable --now "pingify-recycle@$n.timer" >/dev/null 2>&1
                rm -f "$UNIT_DIR/pingify-recycle@$n.timer" "$CFG_DIR/$n.json"
            done
            systemctl daemon-reload
            ok "all tunnels removed"
            pause ;;
        3)  full_uninstall ;;
        0|"") return ;;
    esac
}

full_uninstall() {
    say ""
    warn "this removes the core, every tunnel, the units and the tuning"
    confirm "go ahead?" || return
    local n
    for n in $(tunnel_names); do
        systemctl disable --now "pingify@$n" >/dev/null 2>&1
        systemctl disable --now "pingify-recycle@$n.timer" >/dev/null 2>&1
    done
    systemctl disable --now pingify-health.timer >/dev/null 2>&1
    rm -f "$UNIT_DIR"/pingify@.service "$UNIT_DIR"/pingify-health.service \
          "$UNIT_DIR"/pingify-health.timer "$UNIT_DIR"/pingify-recycle@*.service \
          "$UNIT_DIR"/pingify-recycle@*.timer
    systemctl daemon-reload
    if confirm "also revert the sysctl and file-limit tuning?"; then revert_tuning; fi
    rm -rf "$CFG_DIR" "$STATE_DIR" "$SRC_DIR"
    rm -f "$CORE_BIN"
    ok "Pingify is gone. Removing the manager itself now."
    rm -f "$SELF_BIN"
    say ""
    exit 0
}

# ---------------------------------------------------------------------------
# diagnostics
# ---------------------------------------------------------------------------

tcp_probe() {
    local host="$1" port="$2"
    timeout 5 bash -c ": < /dev/tcp/$host/$port" 2>/dev/null
}

diagnostics_menu() {
    while :; do
        banner
        head2 "Diagnostics"
        item 1 "Reach the other server"
        item 2 "Ping the peer"
        item 3 "Validate every config"
        item 4 "Listening ports"
        item 5 "System summary"
        item 6 "Tail a tunnel log"
        item 0 "Back"
        say ""
        local c=""
        ask c "select"
        case "$c" in
            1) diag_reach ;;
            2) diag_ping ;;
            3) diag_configs ;;
            4) say ""; ss -Hltnp 2>/dev/null | sed 's/^/  /' | head -n 40; pause ;;
            5) diag_system ;;
            6) if pick_tunnel; then journalctl -u "pingify@$PICKED" -n 80 --no-pager | sed 's/^/  /'; pause; fi ;;
            0|"") return ;;
        esac
    done
}

diag_reach() {
    pick_tunnel || return
    cfg_load "$PICKED" || return
    say ""
    if [ -n "$T_CONNECT" ]; then
        local host="${T_CONNECT%:*}" port="${T_CONNECT##*:}"
        info "opening a TCP connection to $host:$port"
        if tcp_probe "$host" "$port"; then
            ok "the peer accepted the connection - the path is clear"
        else
            fail "no answer from $host:$port"
            dim "check that the peer's tunnel is running, that its firewall allows"
            dim "the port, and that the provider is not blocking it"
        fi
    else
        local port="${T_LISTEN##*:}"
        info "this server listens on port $port; checking it is bound"
        if ss -Hltn "sport = :$port" 2>/dev/null | grep -q .; then
            ok "port $port is open and listening"
            dim "run this same check from the other server to test the path"
        else
            fail "nothing is listening on $port - is the tunnel running?"
        fi
    fi
    pause
}

diag_ping() {
    pick_tunnel || return
    cfg_load "$PICKED" || return
    local host=""
    if [ -n "$T_CONNECT" ]; then host="${T_CONNECT%:*}"; fi
    [ -n "$host" ] || ask host "peer IP"
    [ -n "$host" ] || return
    say ""
    ping -c 5 -W 2 "$host" 2>&1 | sed 's/^/  /'
    pause
}

diag_configs() {
    say ""
    local n bad=0
    for n in $(tunnel_names); do
        if "$CORE_BIN" -c "$CFG_DIR/$n.json" -check >/dev/null 2>&1; then
            ok "$n"
        else
            bad=1
            fail "$n"
            "$CORE_BIN" -c "$CFG_DIR/$n.json" -check 2>&1 | sed 's/^/      /'
        fi
    done
    [ "$bad" = "0" ] && dim "every config is valid"
    pause
}

diag_system() {
    say ""
    printf '  %-22s %s\n' "os" "$OS_PRETTY"
    printf '  %-22s %s\n' "kernel" "$(uname -r)"
    printf '  %-22s %s\n' "arch" "$ARCH"
    printf '  %-22s %s\n' "cpu" "$(nproc) cores"
    printf '  %-22s %s\n' "memory" "$(free -h | awk '/^Mem:/{print $3" used of "$2}')"
    printf '  %-22s %s\n' "public ip" "$(public_ip)"
    printf '  %-22s %s\n' "core" "$(core_version)"
    printf '  %-22s %s\n' "watchdog" "$(watchdog_state)"
    printf '  %-22s %s\n' "congestion control" "$(sysctl -n net.ipv4.tcp_congestion_control 2>/dev/null)"
    printf '  %-22s %s\n' "time" "$(date -u '+%Y-%m-%d %H:%M:%S UTC')"
    pause
}

# ---------------------------------------------------------------------------
# backup / restore
# ---------------------------------------------------------------------------

backup_menu() {
    banner
    head2 "Backup & Restore"
    item 1 "Back up every tunnel"
    item 2 "Restore from a backup"
    item 0 "Back"
    say ""
    local c=""
    ask c "select"
    case "$c" in
        1)  say ""
            local out="/root/pingify-backup-$(date +%Y%m%d-%H%M%S).tar.gz"
            if tar -czf "$out" -C / etc/pingify 2>/dev/null; then
                chmod 600 "$out"
                ok "written to $out"
                warn "it contains your shared keys - keep it somewhere safe"
            else
                fail "nothing to back up"
            fi
            pause ;;
        2)  say ""
            local src=""
            ask src "path to the backup file"
            [ -f "$src" ] || { fail "no such file"; pause; return; }
            confirm "this replaces the configs on this server. continue?" || return
            tar -xzf "$src" -C / || { fail "could not unpack it"; pause; return; }
            write_units
            local n
            for n in $(tunnel_names); do service_enable_start "$n"; ok "started $n"; done
            pause ;;
        0|"") return ;;
    esac
}

# ---------------------------------------------------------------------------
# embedded core sources
#
# build.sh drops the contents of core/*.go in here. Shipping the source rather
# than a binary means one file works on amd64 and arm64 alike, and there is
# never a release download to be blocked.
# ---------------------------------------------------------------------------

write_core_sources() {
    local d="$1"
    mkdir -p "$d" || return 1
    cat > "$d/pingify.go" <<'PINGIFY_SRC_EOF'
// Pingify engine - one encrypted tunnel between an Iran server and a server
// abroad, carried over several parallel TCP connections.
//
// Everything lives in this one file on purpose. It is standard-library only:
// Iranian servers frequently cannot reach proxy.golang.org, so the engine has
// to compile with GOPROXY=off and no module downloads of any kind. The only
// companions are tun_linux.go and tun_other.go, which cannot be merged in
// because a Go build constraint applies to a whole file.
//
// Layout:
//     1. configuration and entry point
//     2. logging
//     3. key derivation
//     4. handshake and the carrier pool
//     5. framing, encryption and stream multiplexing
//     6. forward mode - TCP/UDP port forwarding
//     7. tun mode - layer 3
//     8. socket tuning and forward specs
//     9. status endpoint

package main

import (
	"bytes"
	"crypto/aes"
	"crypto/cipher"
	"crypto/hmac"
	"crypto/rand"
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	mrand "math/rand"
	"net"
	"net/http"
	"os"
	"os/exec"
	"os/signal"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

// ==========================================================================
// 1. configuration and entry point
// ==========================================================================

const version = "3.10.0"

// Config is the on-disk tunnel description. One file per tunnel; the same file
// shape is used on both servers, only a few fields differ.
type Config struct {
	Name string `json:"name"`

	// Role decides who owns the user-facing ports.
	//   edge   — users connect here (normally the Iran server)
	//   origin — the real services live here (normally the Kharej server)
	Role string `json:"role"`

	// Mode selects what rides on top of the carrier pool.
	//   forward — TCP/UDP port forwarding
	//   tun     — full layer-3 IP tunnel
	Mode string `json:"mode"`

	// Transport is how the carriers themselves travel. Only "direct" exists
	// today: the core's own encrypted stream with nothing wrapped around it.
	// TLS and WebSocket variants slot in here without touching a line above.
	Transport string `json:"transport,omitempty"`

	// Exactly one of Listen/Connect is set. It is independent of Role, so the
	// dial direction can be chosen to suit whichever side has clean inbound.
	Listen  string `json:"listen,omitempty"`
	Connect string `json:"connect,omitempty"`

	PSK      string `json:"psk"`
	Carriers int    `json:"carriers"`
	WindowKB int    `json:"window_kb"`

	// forward mode: "443", "443=8443", "443=10.0.0.5:8443", "udp:500=500",
	// "8000-8010" (range, same port on the far side).
	Forwards []string `json:"forwards,omitempty"`
	// origin side: if non-empty, only these host:port targets may be dialled.
	Allow []string `json:"allow,omitempty"`

	TUN TUNConfig `json:"tun,omitempty"`

	StatusAddr   string `json:"status_addr,omitempty"`
	KeepaliveSec int    `json:"keepalive_sec,omitempty"`
	DialTimeout  int    `json:"dial_timeout_sec,omitempty"`
	SndBufKB     int    `json:"sndbuf_kb,omitempty"`
	RcvBufKB     int    `json:"rcvbuf_kb,omitempty"`
	LogLevel     string `json:"log_level,omitempty"`
}

type TUNConfig struct {
	Name  string `json:"name,omitempty"`
	Local string `json:"local,omitempty"` // e.g. 10.71.0.1/30
	Peer  string `json:"peer,omitempty"`  // e.g. 10.71.0.2
	MTU   int    `json:"mtu,omitempty"`
}

func (c *Config) applyDefaults() {
	if c.Mode == "" {
		c.Mode = "forward"
	}
	if c.Transport == "" || c.Transport == "tcp" {
		c.Transport = "direct"
	}
	if c.Carriers <= 0 {
		c.Carriers = 4
	}
	if c.Carriers > 64 {
		c.Carriers = 64
	}
	if c.WindowKB <= 0 {
		// 512 KiB per stream is roughly 50 Mbit/s on an 80 ms path, and it
		// bounds what one stalled connection can hold in memory. Raise it for
		// a very fat link; every open stream can buffer this much.
		c.WindowKB = 512
	}
	if c.WindowKB < 64 {
		c.WindowKB = 64
	}
	if c.KeepaliveSec <= 0 {
		c.KeepaliveSec = 10
	}
	if c.DialTimeout <= 0 {
		c.DialTimeout = 10
	}
	if c.SndBufKB <= 0 {
		c.SndBufKB = 4096
	}
	if c.RcvBufKB <= 0 {
		c.RcvBufKB = 4096
	}
	if c.TUN.MTU <= 0 {
		c.TUN.MTU = 1380
	}
	if c.TUN.Name == "" {
		c.TUN.Name = "pfy0"
	}
	if c.LogLevel == "" {
		c.LogLevel = "info"
	}
	if c.Name == "" {
		c.Name = "tunnel"
	}
}

func (c *Config) validate() error {
	switch c.Role {
	case "server", "client":
	default:
		return fmt.Errorf("role must be \"server\" or \"client\", got %q", c.Role)
	}
	switch c.Mode {
	case "forward", "tun":
	default:
		return fmt.Errorf("mode must be \"forward\" or \"tun\", got %q", c.Mode)
	}
	switch c.Transport {
	case "direct":
	default:
		return fmt.Errorf("transport %q is not available in this build", c.Transport)
	}
	if (c.Listen == "") == (c.Connect == "") {
		return fmt.Errorf("set exactly one of \"listen\" or \"connect\"")
	}
	key, err := hex.DecodeString(strings.TrimSpace(c.PSK))
	if err != nil || len(key) < 16 {
		return fmt.Errorf("psk must be a hex string of at least 16 bytes (use -genpsk)")
	}
	if c.Mode == "forward" && c.Role == "server" && len(c.Forwards) == 0 {
		return fmt.Errorf("the IRAN side in forward mode needs at least one entry in \"forwards\"")
	}
	if c.Mode == "tun" && c.Local() == "" {
		return fmt.Errorf("tun mode needs tun.local (e.g. 10.71.0.1/30)")
	}
	return nil
}

func (c *Config) Local() string { return c.TUN.Local }

func (c *Config) key() []byte {
	k, _ := hex.DecodeString(strings.TrimSpace(c.PSK))
	return k
}

func main() {
	var (
		cfgPath = flag.String("c", "", "path to tunnel config JSON")
		genPSK  = flag.Bool("genpsk", false, "print a fresh 32-byte pre-shared key and exit")
		showVer = flag.Bool("version", false, "print version and exit")
		check   = flag.Bool("check", false, "validate the config and exit")
		status  = flag.String("status", "", "print the status of a running tunnel (host:port) and exit")
		healthz = flag.String("healthz", "", "probe a running tunnel (host:port); exit 0 only when a carrier is up")
		brief   = flag.Bool("brief", false, "with -status, print one machine-readable line")
	)
	flag.Parse()

	if *healthz != "" {
		if _, err := fetchStatus(*healthz); err != nil {
			os.Exit(1)
		}
		os.Exit(0)
	}
	if *status != "" {
		os.Exit(printStatus(*status, *brief))
	}

	if *showVer {
		fmt.Println("pingify-core " + version)
		return
	}
	if *genPSK {
		b := make([]byte, 32)
		if _, err := rand.Read(b); err != nil {
			fmt.Fprintln(os.Stderr, "rand:", err)
			os.Exit(1)
		}
		fmt.Println(hex.EncodeToString(b))
		return
	}
	if *cfgPath == "" {
		fmt.Fprintln(os.Stderr, "usage: pingify-core -c /etc/pingify/<name>.json")
		os.Exit(2)
	}

	raw, err := os.ReadFile(*cfgPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "read config:", err)
		os.Exit(1)
	}
	var cfg Config
	if err := json.Unmarshal(raw, &cfg); err != nil {
		fmt.Fprintln(os.Stderr, "parse config:", err)
		os.Exit(1)
	}
	cfg.applyDefaults()
	if err := cfg.validate(); err != nil {
		fmt.Fprintln(os.Stderr, "config:", err)
		os.Exit(1)
	}
	if *check {
		fmt.Println("config OK")
		return
	}

	setLogLevel(cfg.LogLevel)
	logInfo("pingify-core %s starting: tunnel=%s role=%s mode=%s transport=%s carriers=%d",
		version, cfg.Name, cfg.Role, cfg.Mode, cfg.Transport, cfg.Carriers)

	p := newPool(&cfg)
	if err := p.start(); err != nil {
		logError("start: %v", err)
		os.Exit(1)
	}

	var top interface{ Close() error }
	switch cfg.Mode {
	case "forward":
		f, err := startForward(&cfg, p)
		if err != nil {
			logError("forward: %v", err)
			p.close()
			os.Exit(1)
		}
		top = f
	case "tun":
		t, err := startTUN(&cfg, p)
		if err != nil {
			logError("tun: %v", err)
			p.close()
			os.Exit(1)
		}
		top = t
	}

	if cfg.StatusAddr != "" {
		startStatusServer(cfg.StatusAddr, &cfg, p)
	}

	sig := make(chan os.Signal, 1)
	signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)
	s := <-sig
	logInfo("received %s, shutting down", s)
	if top != nil {
		top.Close()
	}
	p.close()
}

// ==========================================================================
// 2. logging
// ==========================================================================

const (
	lvlError = 0
	lvlWarn  = 1
	lvlInfo  = 2
	lvlDebug = 3
)

var logLevel int32 = lvlInfo

func setLogLevel(s string) {
	switch s {
	case "error":
		atomic.StoreInt32(&logLevel, lvlError)
	case "warn":
		atomic.StoreInt32(&logLevel, lvlWarn)
	case "debug":
		atomic.StoreInt32(&logLevel, lvlDebug)
	default:
		atomic.StoreInt32(&logLevel, lvlInfo)
	}
}

func logAt(lvl int32, tag, format string, args ...interface{}) {
	if atomic.LoadInt32(&logLevel) < lvl {
		return
	}
	fmt.Fprintf(os.Stderr, "%s %s %s\n",
		time.Now().Format("2006-01-02 15:04:05"), tag, fmt.Sprintf(format, args...))
}

func logError(f string, a ...interface{}) { logAt(lvlError, "ERR ", f, a...) }
func logWarn(f string, a ...interface{})  { logAt(lvlWarn, "WARN", f, a...) }
func logInfo(f string, a ...interface{})  { logAt(lvlInfo, "INFO", f, a...) }
func logDebug(f string, a ...interface{}) { logAt(lvlDebug, "DBG ", f, a...) }

// ==========================================================================
// 3. key derivation
// ==========================================================================

// HKDF (RFC 5869) over HMAC-SHA256, hand-rolled on crypto/hmac because
// golang.org/x/crypto is off-limits: the engine must build with GOPROXY=off.

func hkdfExtract(salt, ikm []byte) []byte {
	if len(salt) == 0 {
		salt = make([]byte, sha256.Size)
	}
	m := hmac.New(sha256.New, salt)
	m.Write(ikm)
	return m.Sum(nil)
}

func hkdfExpand(prk, info []byte, n int) []byte {
	out := make([]byte, 0, n)
	var t []byte
	for i := byte(1); len(out) < n; i++ {
		m := hmac.New(sha256.New, prk)
		m.Write(t)
		m.Write(info)
		m.Write([]byte{i})
		t = m.Sum(nil)
		out = append(out, t...)
	}
	return out[:n]
}

// sessionKeys is everything one carrier connection needs: an AEAD per
// direction, plus a block cipher per direction used to mask the frame length
// prefix. Masking the length is what stops the stream from looking like clean
// length-delimited framing to anything watching it go past.
type sessionKeys struct {
	tx     cipher.AEAD
	rx     cipher.AEAD
	maskTx cipher.Block
	maskRx cipher.Block
}

func blockFrom(key []byte) cipher.Block {
	b, err := aes.NewCipher(key)
	if err != nil {
		panic(err) // key length is fixed at 32 by the caller
	}
	return b
}

// deriveSession turns the PSK plus both handshake nonces into four independent
// keys. Every carrier gets its own set, because every carrier runs its own
// handshake with fresh nonces - so no two connections, and no two directions,
// ever share a keystream.
func deriveSession(psk, nonceC, nonceS []byte, carrier uint16, dialer bool) *sessionKeys {
	salt := make([]byte, 0, len(nonceC)+len(nonceS)+2)
	salt = append(salt, nonceC...)
	salt = append(salt, nonceS...)
	salt = append(salt, byte(carrier>>8), byte(carrier))
	prk := hkdfExtract(salt, psk)

	c2s := hkdfExpand(prk, []byte("pingify/v3 c2s"), 32)
	s2c := hkdfExpand(prk, []byte("pingify/v3 s2c"), 32)
	lenC2S := hkdfExpand(prk, []byte("pingify/v3 len c2s"), 32)
	lenS2C := hkdfExpand(prk, []byte("pingify/v3 len s2c"), 32)

	if dialer {
		return &sessionKeys{aeadFrom(c2s), aeadFrom(s2c), blockFrom(lenC2S), blockFrom(lenS2C)}
	}
	return &sessionKeys{aeadFrom(s2c), aeadFrom(c2s), blockFrom(lenS2C), blockFrom(lenC2S)}
}

// maskLen XORs the four-byte length prefix with an AES block keyed per
// direction and indexed by the frame counter. One block cipher call per frame
// is nothing next to encrypting the payload, and it removes the last piece of
// visible structure from the stream.
func maskLen(b cipher.Block, ctr uint64, p []byte) {
	var in, out [16]byte
	binary.BigEndian.PutUint64(in[8:], ctr)
	b.Encrypt(out[:], in[:])
	for i := 0; i < 4; i++ {
		p[i] ^= out[i]
	}
}

// ==========================================================================
// 4. handshake and the carrier pool
// ==========================================================================

// ---------------------------------------------------------------------------
// handshake
//
//	dialer  -> listener : NONCE(16) SEALED(16) TAG(32) PAD(0..255)
//	listener -> dialer  : NONCE(16) TAG(32)     PAD(0..255)
//
// Not one byte of this is constant. There is no magic number and no plaintext
// version, role, carrier index or timestamp: those sixteen bytes are XORed
// with an AES block keyed by the pre-shared key and this connection's nonce,
// so two handshakes never share a byte. The length varies too, because the
// amount of trailing padding is read out of the tag - unpredictable to an
// observer, known to both ends.
//
// That matters more than it sounds. The previous revision opened every
// connection with the four ASCII bytes "PFY2", which is a one-line signature
// for anything doing deep packet inspection.
//
// A wrong key, a stale timestamp or a replayed nonce all end the same way: the
// socket closes after a random delay without a byte of reply, so a scanner
// cannot tell the port from a black hole.
// ---------------------------------------------------------------------------

const (
	hsVersion   = 3
	hsNonceLen  = 16
	hsSealedLen = 16
	hsTagLen    = 32
	hsClientLen = hsNonceLen + hsSealedLen + hsTagLen
	hsServerLen = hsNonceLen + hsTagLen
	hsSkew      = 180 * time.Second
)

var errHandshake = errors.New("handshake rejected")

func roleByte(role string) byte {
	if role == "server" {
		return 0
	}
	return 1
}

type replayGuard struct {
	mu   sync.Mutex
	seen map[[16]byte]int64
}

func newReplayGuard() *replayGuard {
	g := &replayGuard{seen: make(map[[16]byte]int64)}
	go func() {
		t := time.NewTicker(time.Minute)
		for range t.C {
			cut := time.Now().Add(-2 * hsSkew).UnixNano()
			g.mu.Lock()
			for k, v := range g.seen {
				if v < cut {
					delete(g.seen, k)
				}
			}
			g.mu.Unlock()
		}
	}()
	return g
}

func (g *replayGuard) accept(n [16]byte) bool {
	g.mu.Lock()
	defer g.mu.Unlock()
	if _, dup := g.seen[n]; dup {
		return false
	}
	g.seen[n] = time.Now().UnixNano()
	return true
}

func aeadFrom(key []byte) cipher.AEAD {
	blk, err := aes.NewCipher(key)
	if err != nil {
		panic(err) // key length is fixed at 32 by deriveKeys
	}
	a, err := cipher.NewGCM(blk)
	if err != nil {
		panic(err)
	}
	return a
}

// headerPad XORs the 16 header bytes with a one-time AES block keyed by the
// pre-shared key and this connection's nonce. Both ends can compute it; nobody
// else can, and the result carries no recognisable structure.
func headerPad(psk, nonce []byte) [16]byte {
	k := hkdfExpand(hkdfExtract(nonce, psk), []byte("pingify/v3 header"), 32)
	blk, err := aes.NewCipher(k)
	if err != nil {
		panic(err)
	}
	var out [16]byte
	blk.Encrypt(out[:], nonce)
	return out
}

// writePadding appends the trailing random bytes. The count comes out of the
// tag, so the handshake is never the same length twice.
func writePadding(conn net.Conn, tag []byte) error {
	n := int(tag[0])
	if n == 0 {
		return nil
	}
	pad := make([]byte, n)
	if _, err := rand.Read(pad); err != nil {
		return err
	}
	_, err := conn.Write(pad)
	return err
}

func readPadding(conn net.Conn, tag []byte) error {
	n := int(tag[0])
	if n == 0 {
		return nil
	}
	_, err := io.CopyN(io.Discard, conn, int64(n))
	return err
}

// clientHandshake runs on the side that dials out.
func clientHandshake(conn net.Conn, cfg *Config, carrier int) (*sessionKeys, error) {
	psk := cfg.key()
	buf := make([]byte, hsClientLen)
	nonceC := buf[:hsNonceLen]
	sealed := buf[hsNonceLen : hsNonceLen+hsSealedLen]
	tag := buf[hsNonceLen+hsSealedLen:]

	if _, err := rand.Read(nonceC); err != nil {
		return nil, err
	}
	var hdr [16]byte
	hdr[0] = hsVersion
	hdr[1] = roleByte(cfg.Role)
	binary.BigEndian.PutUint16(hdr[2:4], uint16(carrier))
	binary.BigEndian.PutUint64(hdr[4:12], uint64(time.Now().Unix()))
	if _, err := rand.Read(hdr[12:]); err != nil { // filler, never inspected
		return nil, err
	}
	pad := headerPad(psk, nonceC)
	for i := range hdr {
		sealed[i] = hdr[i] ^ pad[i]
	}
	m := hmac.New(sha256.New, psk)
	m.Write(nonceC)
	m.Write(sealed)
	copy(tag, m.Sum(nil))

	conn.SetDeadline(time.Now().Add(15 * time.Second))
	if _, err := conn.Write(buf); err != nil {
		return nil, err
	}
	if err := writePadding(conn, tag); err != nil {
		return nil, err
	}

	resp := make([]byte, hsServerLen)
	if _, err := io.ReadFull(conn, resp); err != nil {
		return nil, err
	}
	m2 := hmac.New(sha256.New, psk)
	m2.Write([]byte("pingify/v3 server"))
	m2.Write(nonceC)
	m2.Write(resp[:hsNonceLen])
	if !hmac.Equal(m2.Sum(nil), resp[hsNonceLen:]) {
		return nil, errHandshake
	}
	if err := readPadding(conn, resp[hsNonceLen:]); err != nil {
		return nil, err
	}
	conn.SetDeadline(time.Time{})

	return deriveSession(psk, nonceC, resp[:hsNonceLen], uint16(carrier), true), nil
}

// serverHandshake runs on the side that listens.
func serverHandshake(conn net.Conn, cfg *Config, g *replayGuard) (*sessionKeys, int, error) {
	psk := cfg.key()
	buf := make([]byte, hsClientLen)
	conn.SetDeadline(time.Now().Add(15 * time.Second))
	if _, err := io.ReadFull(conn, buf); err != nil {
		return nil, 0, err
	}
	nonceC := buf[:hsNonceLen]
	sealed := buf[hsNonceLen : hsNonceLen+hsSealedLen]
	tag := buf[hsNonceLen+hsSealedLen:]

	// Authenticate before trusting a single field.
	m := hmac.New(sha256.New, psk)
	m.Write(nonceC)
	m.Write(sealed)
	if !hmac.Equal(m.Sum(nil), tag) {
		return nil, 0, errHandshake
	}
	var nc [16]byte
	copy(nc[:], nonceC)
	if !g.accept(nc) {
		return nil, 0, errHandshake
	}

	pad := headerPad(psk, nonceC)
	var hdr [16]byte
	for i := range hdr {
		hdr[i] = sealed[i] ^ pad[i]
	}
	if hdr[0] != hsVersion {
		return nil, 0, errHandshake
	}
	if hdr[1] == roleByte(cfg.Role) {
		return nil, 0, errHandshake // both ends configured with the same role
	}
	ts := int64(binary.BigEndian.Uint64(hdr[4:12]))
	if d := time.Since(time.Unix(ts, 0)); d > hsSkew || d < -hsSkew {
		return nil, 0, errHandshake
	}
	carrier := int(binary.BigEndian.Uint16(hdr[2:4]))

	if err := readPadding(conn, tag); err != nil {
		return nil, 0, err
	}

	resp := make([]byte, hsServerLen)
	if _, err := rand.Read(resp[:hsNonceLen]); err != nil {
		return nil, 0, err
	}
	m2 := hmac.New(sha256.New, psk)
	m2.Write([]byte("pingify/v3 server"))
	m2.Write(nonceC)
	m2.Write(resp[:hsNonceLen])
	copy(resp[hsNonceLen:], m2.Sum(nil))
	if _, err := conn.Write(resp); err != nil {
		return nil, 0, err
	}
	if err := writePadding(conn, resp[hsNonceLen:]); err != nil {
		return nil, 0, err
	}
	conn.SetDeadline(time.Time{})

	return deriveSession(psk, nonceC, resp[:hsNonceLen], uint16(carrier), false), carrier, nil
}

// ---------------------------------------------------------------------------
// carrier pool
// ---------------------------------------------------------------------------

const maxCarriers = 64

type recordHandler interface {
	onRecord(l *link, cmd byte, id uint32, body []byte)
	onLinkDown(l *link)
}

type pool struct {
	cfg *Config

	mu    sync.RWMutex
	links [maxCarriers]*link
	h     recordHandler

	ln        net.Listener
	guard     *replayGuard
	closed    chan struct{}
	closeOnce sync.Once

	startedAt time.Time
}

func newPool(cfg *Config) *pool {
	return &pool{cfg: cfg, guard: newReplayGuard(), closed: make(chan struct{}), startedAt: time.Now()}
}

func (p *pool) setHandler(h recordHandler) {
	p.mu.Lock()
	p.h = h
	p.mu.Unlock()
}

func (p *pool) handler() recordHandler {
	p.mu.RLock()
	h := p.h
	p.mu.RUnlock()
	return h
}

func (p *pool) start() error {
	if p.cfg.Connect != "" {
		for i := 0; i < p.cfg.Carriers; i++ {
			go p.dialLoop(i)
		}
		logInfo("dialling %d carriers to %s", p.cfg.Carriers, p.cfg.Connect)
		return nil
	}
	ln, err := net.Listen("tcp", p.cfg.Listen)
	if err != nil {
		return err
	}
	p.ln = ln
	go p.acceptLoop(ln)
	logInfo("waiting for carriers on %s", p.cfg.Listen)
	return nil
}

func (p *pool) acceptLoop(ln net.Listener) {
	for {
		conn, err := ln.Accept()
		if err != nil {
			select {
			case <-p.closed:
				return
			default:
			}
			logWarn("accept: %v", err)
			time.Sleep(200 * time.Millisecond)
			continue
		}
		go p.serveInbound(conn)
	}
}

func (p *pool) serveInbound(conn net.Conn) {
	tuneSocket(conn, p.cfg)
	keys, idx, err := serverHandshake(conn, p.cfg, p.guard)
	if err != nil {
		// Stay quiet: a probe should learn nothing from timing or content.
		time.Sleep(time.Duration(200+mrand.Intn(600)) * time.Millisecond)
		conn.Close()
		logDebug("rejected %s: %v", conn.RemoteAddr(), err)
		return
	}
	if idx < 0 || idx >= maxCarriers {
		conn.Close()
		return
	}
	l := newLink(idx, p.cfg, conn, keys, p)
	p.install(idx, l)
	logInfo("carrier %d up from %s", idx, conn.RemoteAddr())
	l.run()
}

func (p *pool) dialLoop(idx int) {
	backoff := 500 * time.Millisecond
	for {
		select {
		case <-p.closed:
			return
		default:
		}
		conn, err := net.DialTimeout("tcp", p.cfg.Connect, time.Duration(p.cfg.DialTimeout)*time.Second)
		if err != nil {
			logWarn("carrier %d dial %s: %v", idx, p.cfg.Connect, err)
			p.sleepBackoff(&backoff)
			continue
		}
		tuneSocket(conn, p.cfg)
		keys, err := clientHandshake(conn, p.cfg, idx)
		if err != nil {
			conn.Close()
			logWarn("carrier %d handshake: %v (check the key on both servers)", idx, err)
			p.sleepBackoff(&backoff)
			continue
		}
		backoff = 500 * time.Millisecond
		l := newLink(idx, p.cfg, conn, keys, p)
		p.install(idx, l)
		logInfo("carrier %d up to %s", idx, p.cfg.Connect)
		l.run() // blocks until the carrier dies
		select {
		case <-p.closed:
			return
		case <-time.After(300 * time.Millisecond):
		}
	}
}

func (p *pool) sleepBackoff(b *time.Duration) {
	j := time.Duration(mrand.Int63n(int64(*b/2 + 1)))
	select {
	case <-time.After(*b + j):
	case <-p.closed:
	}
	if *b < 8*time.Second {
		*b *= 2
	}
}

func (p *pool) install(idx int, l *link) {
	p.mu.Lock()
	old := p.links[idx]
	p.links[idx] = l
	p.mu.Unlock()
	if old != nil && old != l {
		old.close()
	}
}

// pick returns the live carrier with the fewest open streams. Spreading
// streams this way keeps every carrier's congestion window busy, which is the
// whole point of running more than one.
func (p *pool) pick() *link {
	p.mu.RLock()
	defer p.mu.RUnlock()
	var best *link
	bestN := 1 << 30
	for _, l := range p.links {
		if l == nil || !l.alive() {
			continue
		}
		if n := l.streamCount(); n < bestN {
			best, bestN = l, n
		}
	}
	return best
}

// pickHash pins a flow to a carrier by hash so that packets of one inner
// connection always take the same path and never arrive out of order.
func (p *pool) pickHash(h uint32) *link {
	p.mu.RLock()
	defer p.mu.RUnlock()
	n := 0
	for _, l := range p.links {
		if l != nil && l.alive() {
			n++
		}
	}
	if n == 0 {
		return nil
	}
	// Two passes rather than building a slice: in tun mode this runs once per
	// packet, and an allocation there would show up as GC pressure.
	k := int(h % uint32(n))
	for _, l := range p.links {
		if l != nil && l.alive() {
			if k == 0 {
				return l
			}
			k--
		}
	}
	return nil
}

func (p *pool) liveLinks() []*link {
	p.mu.RLock()
	defer p.mu.RUnlock()
	out := make([]*link, 0, maxCarriers)
	for _, l := range p.links {
		if l != nil {
			out = append(out, l)
		}
	}
	return out
}

func (p *pool) close() {
	p.closeOnce.Do(func() {
		close(p.closed)
		if p.ln != nil {
			p.ln.Close()
		}
		p.mu.Lock()
		links := p.links
		p.links = [maxCarriers]*link{}
		p.mu.Unlock()
		for _, l := range links {
			if l != nil {
				l.close()
			}
		}
	})
}

func (p *pool) stats() (up int, tx, rx uint64, rttUS int64) {
	for _, l := range p.liveLinks() {
		if !l.alive() {
			continue
		}
		up++
		tx += atomic.LoadUint64(&l.txBytes)
		rx += atomic.LoadUint64(&l.rxBytes)
		if r := atomic.LoadInt64(&l.rttUS); r > rttUS {
			rttUS = r
		}
	}
	return
}

// ==========================================================================
// 5. framing, encryption and stream multiplexing
// ==========================================================================

// ---------------------------------------------------------------------------
// wire format
//
// Every carrier connection carries a stream of frames:
//
//	[4-byte big-endian ciphertext length][AES-256-GCM ciphertext]
//
// The plaintext of a frame is one or more back-to-back records:
//
//	[1-byte cmd][4-byte stream id][4-byte payload length][payload]
//
// The writer coalesces everything queued at that instant into a single frame,
// so a burst of small packets costs one seal and one write syscall instead of
// dozens. That batching is most of the throughput win over a naive tunnel.
// ---------------------------------------------------------------------------

const (
	recHdr    = 9
	maxRecord = 32 * 1024
	maxPlain  = 128 * 1024
	maxFrame  = maxPlain + 64

	// Control records - window credits, keepalives, opens and closes - are a
	// handful of bytes each and vastly outnumber data records. Giving them
	// their own small pool keeps a four-byte credit update from borrowing a
	// 32 KiB buffer, which is where most of the idle memory used to go.
	smallRecord = 512

	sendQueue      = 128 // records queued per carrier before the writer blocks
	earlyPadFrames = 8   // pad only the opening frames of a connection
	earlyPadMax    = 512
)

const (
	cmdData = 1  // stream payload
	cmdSYN  = 2  // open TCP stream; payload = target "host:port"
	cmdFIN  = 3  // half-close: no more data from this side
	cmdRST  = 4  // hard close
	cmdWND  = 5  // flow-control credit; payload = 4-byte byte count
	cmdPing = 6  // payload = 8-byte stamp
	cmdPong = 7  // echo of the ping payload
	cmdUSYN = 8  // open UDP session; payload = target "host:port"
	cmdUDP  = 9  // one UDP datagram
	cmdUFIN = 10 // UDP session gone
	cmdTUN  = 11 // one raw IP packet (tun mode)
	cmdPad  = 12 // random filler, discarded on arrival
)

var errLinkClosed = errors.New("carrier closed")

// ---------------------------------------------------------------------------
// pooled records
// ---------------------------------------------------------------------------

type recBuf struct {
	a   []byte
	n   int
	big bool
}

func (r *recBuf) body() []byte  { return r.a[recHdr:] }
func (r *recBuf) bytes() []byte { return r.a[:r.n] }

func (r *recBuf) seal(cmd byte, id uint32, n int) {
	r.a[0] = cmd
	binary.BigEndian.PutUint32(r.a[1:5], id)
	binary.BigEndian.PutUint32(r.a[5:9], uint32(n))
	r.n = recHdr + n
}

var bigPool = sync.Pool{New: func() interface{} {
	return &recBuf{a: make([]byte, recHdr+maxRecord), big: true}
}}

var smallPool = sync.Pool{New: func() interface{} {
	return &recBuf{a: make([]byte, recHdr+smallRecord)}
}}

// getRec hands out a full-size buffer, for the data path.
func getRec() *recBuf { return bigPool.Get().(*recBuf) }

// getCtrl sizes the buffer to the payload, so a keepalive does not cost 32 KiB.
func getCtrl(payload int) *recBuf {
	if payload <= smallRecord {
		return smallPool.Get().(*recBuf)
	}
	return bigPool.Get().(*recBuf)
}

func putRec(r *recBuf) {
	if r.big {
		bigPool.Put(r)
	} else {
		smallPool.Put(r)
	}
}

func ctrlRec(cmd byte, id uint32, payload []byte) *recBuf {
	r := getCtrl(len(payload))
	copy(r.a[recHdr:], payload)
	r.seal(cmd, id, len(payload))
	return r
}

// appendPad tacks a random-length filler record onto a frame.
func appendPad(frame []byte) []byte {
	n := mrand.Intn(earlyPadMax)
	if n == 0 {
		return frame
	}
	var hdr [recHdr]byte
	hdr[0] = cmdPad
	binary.BigEndian.PutUint32(hdr[5:9], uint32(n))
	frame = append(frame, hdr[:]...)
	start := len(frame)
	frame = append(frame, make([]byte, n)...)
	rand.Read(frame[start:])
	return frame
}

// ---------------------------------------------------------------------------
// receive buffer: byte-bounded, never blocks the carrier reader
// ---------------------------------------------------------------------------

type recvBuf struct {
	mu  sync.Mutex
	cv  *sync.Cond
	buf bytes.Buffer
	eof bool
	err error
}

func newRecvBuf() *recvBuf {
	r := &recvBuf{}
	r.cv = sync.NewCond(&r.mu)
	return r
}

func (r *recvBuf) push(p []byte) {
	r.mu.Lock()
	if r.err == nil && !r.eof {
		r.buf.Write(p)
	}
	r.cv.Broadcast()
	r.mu.Unlock()
}

func (r *recvBuf) Read(p []byte) (int, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for r.buf.Len() == 0 {
		if r.err != nil {
			return 0, r.err
		}
		if r.eof {
			return 0, io.EOF
		}
		r.cv.Wait()
	}
	return r.buf.Read(p)
}

func (r *recvBuf) closeEOF() {
	r.mu.Lock()
	r.eof = true
	r.cv.Broadcast()
	r.mu.Unlock()
}

func (r *recvBuf) fail(err error) {
	r.mu.Lock()
	if r.err == nil {
		r.err = err
	}
	r.cv.Broadcast()
	r.mu.Unlock()
}

// ---------------------------------------------------------------------------
// stream
// ---------------------------------------------------------------------------

// stream is one multiplexed TCP connection riding a single carrier. It never
// migrates between carriers: a stream is pinned at open time so its bytes can
// never be reordered by uneven carrier latency, which is what would otherwise
// make the inner TCP connection collapse.
type stream struct {
	id     uint32
	l      *link
	rb     *recvBuf
	win    int32
	winCh  chan struct{}
	done   chan struct{}
	once   sync.Once
	halves int32

	lmu   sync.Mutex
	local net.Conn
	dead  bool
}

// attach hands the stream its local socket. A stream is registered the moment
// its SYN is parsed, before the dial finishes, so that data arriving right
// behind the SYN is buffered instead of dropped; attach closes that gap.
func (s *stream) attach(c net.Conn) bool {
	s.lmu.Lock()
	defer s.lmu.Unlock()
	if s.dead {
		return false
	}
	s.local = c
	return true
}

// halfDone retires the stream once both directions have finished. Without it
// a completed connection would sit in the carrier's stream table forever and
// its local socket would never be closed.
func (s *stream) halfDone() {
	if atomic.AddInt32(&s.halves, 1) == 2 {
		s.reset()
	}
}

func (s *stream) acquireUpTo(max int32) int32 {
	for {
		cur := atomic.LoadInt32(&s.win)
		if cur > 0 {
			n := cur
			if n > max {
				n = max
			}
			if atomic.CompareAndSwapInt32(&s.win, cur, cur-n) {
				return n
			}
			continue
		}
		select {
		case <-s.winCh:
		case <-s.done:
			return 0
		case <-s.l.closed:
			return 0
		}
	}
}

func (s *stream) addWin(n int32) {
	if n <= 0 {
		return
	}
	atomic.AddInt32(&s.win, n)
	select {
	case s.winCh <- struct{}{}:
	default:
	}
}

// pumpOut moves bytes from the local socket into the carrier, never sending
// more than the credit the far side has granted.
func (s *stream) pumpOut(local net.Conn) {
	defer s.halfDone()
	defer s.l.send(ctrlRec(cmdFIN, s.id, nil))
	for {
		credit := s.acquireUpTo(maxRecord)
		if credit == 0 {
			return
		}
		r := getRec()
		n, err := local.Read(r.body()[:credit])
		if n > 0 {
			r.seal(cmdData, s.id, n)
			atomic.AddUint64(&s.l.txBytes, uint64(n))
			if !s.l.send(r) {
				return
			}
		} else {
			putRec(r)
		}
		s.addWin(credit - int32(n)) // hand back the slice we did not use
		if err != nil {
			return
		}
	}
}

// pumpIn drains the receive buffer into the local socket and returns the
// consumed credit to the far side.
func (s *stream) pumpIn(local net.Conn) {
	defer s.halfDone()
	buf := make([]byte, 32*1024)
	for {
		n, err := s.rb.Read(buf)
		if n > 0 {
			if _, werr := local.Write(buf[:n]); werr != nil {
				s.reset()
				return
			}
			atomic.AddUint64(&s.l.rxBytes, uint64(n))
			var c [4]byte
			binary.BigEndian.PutUint32(c[:], uint32(n))
			s.l.send(ctrlRec(cmdWND, s.id, c[:]))
		}
		if err != nil {
			// Far side stopped sending: half-close so the local peer sees EOF
			// but can still finish its own upload.
			if cw, ok := local.(interface{ CloseWrite() error }); ok {
				cw.CloseWrite()
			} else {
				s.reset()
			}
			return
		}
	}
}

func (s *stream) reset() {
	s.once.Do(func() {
		close(s.done)
		s.rb.fail(errLinkClosed)
		s.lmu.Lock()
		s.dead = true
		c := s.local
		s.lmu.Unlock()
		if c != nil {
			c.Close()
		}
		s.l.removeStream(s.id)
	})
}

// ---------------------------------------------------------------------------
// link
// ---------------------------------------------------------------------------

type link struct {
	idx  int
	cfg  *Config
	conn net.Conn
	pool *pool

	keys  *sessionKeys
	txCtr uint64
	rxCtr uint64

	sendQ     chan *recBuf
	closed    chan struct{}
	closeOnce sync.Once

	mu      sync.Mutex
	streams map[uint32]*stream
	nextID  uint32

	txBytes uint64
	rxBytes uint64
	lastRx  int64 // unix nano
	rttUS   int64
	upSince int64
}

func newLink(idx int, cfg *Config, conn net.Conn, k *sessionKeys, p *pool) *link {
	l := &link{
		idx: idx, cfg: cfg, conn: conn, pool: p,
		keys:    k,
		sendQ:   make(chan *recBuf, sendQueue),
		closed:  make(chan struct{}),
		streams: make(map[uint32]*stream),
	}
	// Odd ids from IRAN, even from KHAREJ. Ids are per-carrier, so this
	// is only belt and braces against a future origin-initiated stream.
	if cfg.Role == "server" {
		l.nextID = 1
	} else {
		l.nextID = 2
	}
	now := time.Now().UnixNano()
	atomic.StoreInt64(&l.lastRx, now)
	atomic.StoreInt64(&l.upSince, now)
	return l
}

func (l *link) run() {
	go l.writeLoop()
	go l.keepaliveLoop()
	l.readLoop()
}

func (l *link) alive() bool {
	select {
	case <-l.closed:
		return false
	default:
		return true
	}
}

func (l *link) send(r *recBuf) bool {
	select {
	case l.sendQ <- r:
		return true
	case <-l.closed:
		putRec(r)
		return false
	}
}

func (l *link) trySend(r *recBuf) bool {
	select {
	case l.sendQ <- r:
		return true
	default:
		putRec(r)
		return false
	}
}

func nonceFor(ctr uint64) [12]byte {
	var n [12]byte
	binary.BigEndian.PutUint64(n[4:], ctr)
	return n
}

func (l *link) writeLoop() {
	defer l.close()
	frame := make([]byte, 0, maxPlain)
	out := make([]byte, 0, 4+maxPlain+32)
	for {
		var r *recBuf
		select {
		case r = <-l.sendQ:
		case <-l.closed:
			return
		}
		frame = append(frame[:0], r.bytes()...)
		putRec(r)
	drain:
		for len(frame) <= maxPlain-recHdr-maxRecord {
			select {
			case r2 := <-l.sendQ:
				frame = append(frame, r2.bytes()...)
				putRec(r2)
			default:
				break drain
			}
		}
		// Only the opening frames are padded. That is where a fingerprint
		// would be taken, and padding every frame would cost real bandwidth.
		if ctr := l.txCtr; ctr < earlyPadFrames && len(frame) < maxPlain-recHdr-earlyPadMax {
			frame = appendPad(frame)
		}
		ctr := l.txCtr
		l.txCtr++
		n := nonceFor(ctr)
		out = out[:4]
		out = l.keys.tx.Seal(out, n[:], frame, nil)
		binary.BigEndian.PutUint32(out[:4], uint32(len(out)-4))
		maskLen(l.keys.maskTx, ctr, out[:4])
		l.conn.SetWriteDeadline(time.Now().Add(60 * time.Second))
		if _, err := l.conn.Write(out); err != nil {
			logDebug("carrier %d write: %v", l.idx, err)
			return
		}
		out = out[:0]
	}
}

func (l *link) readLoop() {
	defer l.close()
	var hdr [4]byte
	ct := make([]byte, 0, maxFrame)
	plain := make([]byte, 0, maxPlain)
	idle := time.Duration(l.cfg.KeepaliveSec) * time.Second * 3
	for {
		l.conn.SetReadDeadline(time.Now().Add(idle))
		if _, err := io.ReadFull(l.conn, hdr[:]); err != nil {
			logDebug("carrier %d read: %v", l.idx, err)
			return
		}
		maskLen(l.keys.maskRx, l.rxCtr, hdr[:]) // XOR is its own inverse
		n := int(binary.BigEndian.Uint32(hdr[:]))
		if n < 16 || n > maxFrame {
			logWarn("carrier %d: bad frame length %d", l.idx, n)
			return
		}
		if cap(ct) < n {
			ct = make([]byte, 0, n)
		}
		ct = ct[:n]
		if _, err := io.ReadFull(l.conn, ct); err != nil {
			return
		}
		nc := nonceFor(l.rxCtr)
		l.rxCtr++
		p, err := l.keys.rx.Open(plain[:0], nc[:], ct, nil)
		if err != nil {
			logWarn("carrier %d: authentication failed", l.idx)
			return
		}
		plain = p[:0]
		atomic.StoreInt64(&l.lastRx, time.Now().UnixNano())
		if err := l.dispatch(p); err != nil {
			logWarn("carrier %d: %v", l.idx, err)
			return
		}
	}
}

func (l *link) dispatch(p []byte) error {
	for len(p) > 0 {
		if len(p) < recHdr {
			return fmt.Errorf("truncated record header")
		}
		cmd := p[0]
		id := binary.BigEndian.Uint32(p[1:5])
		n := int(binary.BigEndian.Uint32(p[5:9]))
		if n > maxRecord || len(p) < recHdr+n {
			return fmt.Errorf("truncated record body")
		}
		body := p[recHdr : recHdr+n]
		p = p[recHdr+n:]

		switch cmd {
		case cmdData:
			if s := l.getStream(id); s != nil {
				s.rb.push(body)
			}
		case cmdWND:
			if n == 4 {
				if s := l.getStream(id); s != nil {
					s.addWin(int32(binary.BigEndian.Uint32(body)))
				}
			}
		case cmdFIN:
			if s := l.getStream(id); s != nil {
				s.rb.closeEOF()
			}
		case cmdRST:
			if s := l.getStream(id); s != nil {
				s.reset()
			}
		case cmdPad:
			// deliberately ignored
		case cmdPing:
			// Never block the read loop: if the send queue is momentarily
			// full, drop the pong rather than risk both ends stalling on
			// each other's socket buffers.
			l.trySend(ctrlRec(cmdPong, 0, body))
		case cmdPong:
			if n == 8 {
				sent := int64(binary.BigEndian.Uint64(body))
				atomic.StoreInt64(&l.rttUS, (time.Now().UnixNano()-sent)/1000)
			}
		case cmdSYN, cmdUSYN, cmdUDP, cmdUFIN, cmdTUN:
			if h := l.pool.handler(); h != nil {
				h.onRecord(l, cmd, id, body)
			}
		default:
			logDebug("carrier %d: unknown cmd %d", l.idx, cmd)
		}
	}
	return nil
}

func (l *link) keepaliveLoop() {
	t := time.NewTicker(time.Duration(l.cfg.KeepaliveSec) * time.Second)
	defer t.Stop()
	idle := int64(l.cfg.KeepaliveSec) * 3 * int64(time.Second)
	for {
		select {
		case <-t.C:
			if time.Now().UnixNano()-atomic.LoadInt64(&l.lastRx) > idle {
				logWarn("carrier %d: silent for %ds, recycling", l.idx, l.cfg.KeepaliveSec*3)
				l.close()
				return
			}
			var b [8]byte
			binary.BigEndian.PutUint64(b[:], uint64(time.Now().UnixNano()))
			l.send(ctrlRec(cmdPing, 0, b[:]))
		case <-l.closed:
			return
		}
	}
}

func (l *link) close() {
	l.closeOnce.Do(func() {
		close(l.closed)
		l.conn.Close()
		l.mu.Lock()
		streams := make([]*stream, 0, len(l.streams))
		for _, s := range l.streams {
			streams = append(streams, s)
		}
		l.streams = make(map[uint32]*stream)
		l.mu.Unlock()
		for _, s := range streams {
			s.reset()
		}
		if l.pool != nil {
			if h := l.pool.handler(); h != nil {
				h.onLinkDown(l)
			}
		}
		logInfo("carrier %d down", l.idx)
	})
}

// ---------------------------------------------------------------------------
// stream table
// ---------------------------------------------------------------------------

func (l *link) window() int32 { return int32(l.cfg.WindowKB) * 1024 }

func (l *link) newStream(local net.Conn) *stream {
	l.mu.Lock()
	id := l.nextID
	l.nextID += 2
	s := l.mkStream(id, local)
	l.streams[id] = s
	l.mu.Unlock()
	return s
}

func (l *link) acceptStream(id uint32, local net.Conn) *stream {
	l.mu.Lock()
	if _, dup := l.streams[id]; dup {
		l.mu.Unlock()
		return nil
	}
	s := l.mkStream(id, local)
	l.streams[id] = s
	l.mu.Unlock()
	return s
}

func (l *link) mkStream(id uint32, local net.Conn) *stream {
	return &stream{
		id:    id,
		l:     l,
		rb:    newRecvBuf(),
		win:   l.window(),
		winCh: make(chan struct{}, 1),
		done:  make(chan struct{}),
		local: local,
	}
}

func (l *link) getStream(id uint32) *stream {
	l.mu.Lock()
	s := l.streams[id]
	l.mu.Unlock()
	return s
}

func (l *link) removeStream(id uint32) {
	l.mu.Lock()
	delete(l.streams, id)
	l.mu.Unlock()
}

func (l *link) streamCount() int {
	l.mu.Lock()
	n := len(l.streams)
	l.mu.Unlock()
	return n
}

// ==========================================================================
// 6. forward mode - TCP/UDP port forwarding
// ==========================================================================

// forward mode: the edge owns the user-facing ports and the origin owns the
// real services. Everything in between rides the carrier pool.

const (
	udpIDBit    = 0x80000000
	udpIdleSec  = 90
	udpReadSize = 64 * 1024
)

type sessKey struct {
	l  *link
	id uint32
}

type udpSess struct {
	l   *link
	id  uint32
	pc  net.PacketConn
	cli net.Addr // edge side: where the client's datagrams came from
	key string   // edge side: map key

	// The origin dials the real service off the carrier's read loop, so that
	// a slow DNS lookup cannot stall every other stream on that carrier.
	// Datagrams that arrive while the dial is in flight wait here instead of
	// being dropped - losing the first packet of a UDP exchange would often
	// mean losing the whole exchange.
	mu      sync.Mutex
	uc      *net.UDPConn
	pending [][]byte
	dialed  bool

	last int64
}

const udpPendingMax = 8

// deliver hands one datagram to the real service, queueing it if the socket is
// not ready yet.
func (s *udpSess) deliver(b []byte) {
	s.mu.Lock()
	if s.uc != nil {
		uc := s.uc
		s.mu.Unlock()
		uc.Write(b)
		return
	}
	if !s.dialed && len(s.pending) < udpPendingMax {
		s.pending = append(s.pending, append([]byte(nil), b...))
	}
	s.mu.Unlock()
}

// ready installs the dialled socket and flushes whatever queued up.
func (s *udpSess) ready(uc *net.UDPConn) {
	s.mu.Lock()
	s.uc = uc
	s.dialed = true
	q := s.pending
	s.pending = nil
	s.mu.Unlock()
	for _, b := range q {
		uc.Write(b)
	}
}

func (s *udpSess) socket() *net.UDPConn {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.uc
}

type forwarder struct {
	cfg *Config
	p   *pool

	listeners []net.Listener
	packets   []net.PacketConn

	mu    sync.Mutex
	edge  map[string]*udpSess  // edge: "lport|clientaddr" -> session
	byID  map[sessKey]*udpSess // both sides: (carrier, id) -> session
	udpSq uint32

	allow  map[string]bool
	closed chan struct{}
	once   sync.Once
}

func startForward(cfg *Config, p *pool) (*forwarder, error) {
	f := &forwarder{
		cfg:    cfg,
		p:      p,
		edge:   make(map[string]*udpSess),
		byID:   make(map[sessKey]*udpSess),
		closed: make(chan struct{}),
	}
	if len(cfg.Allow) > 0 {
		f.allow = make(map[string]bool, len(cfg.Allow))
		for _, a := range cfg.Allow {
			f.allow[a] = true
		}
	}
	p.setHandler(f)

	if cfg.Role == "server" {
		for _, spec := range cfg.Forwards {
			rules, err := parseForward(spec)
			if err != nil {
				f.Close()
				return nil, err
			}
			for _, r := range rules {
				if err := f.bind(r); err != nil {
					f.Close()
					return nil, err
				}
			}
		}
	}
	go f.reapUDP()
	return f, nil
}

func (f *forwarder) bind(r fwdRule) error {
	addr := fmt.Sprintf(":%d", r.lport)
	if r.proto == "udp" {
		pc, err := net.ListenPacket("udp", addr)
		if err != nil {
			return fmt.Errorf("listen udp %s: %v", addr, err)
		}
		f.packets = append(f.packets, pc)
		go f.serveUDP(pc, r)
		logInfo("forward udp %s -> %s", addr, r.target)
		return nil
	}
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		return fmt.Errorf("listen tcp %s: %v", addr, err)
	}
	f.listeners = append(f.listeners, ln)
	go f.serveTCP(ln, r)
	logInfo("forward tcp %s -> %s", addr, r.target)
	return nil
}

// ---------------------------------------------------------------------------
// edge: TCP
// ---------------------------------------------------------------------------

func (f *forwarder) serveTCP(ln net.Listener, r fwdRule) {
	for {
		c, err := ln.Accept()
		if err != nil {
			select {
			case <-f.closed:
				return
			default:
			}
			logWarn("accept :%d: %v", r.lport, err)
			time.Sleep(100 * time.Millisecond)
			continue
		}
		go f.openStream(c, r)
	}
}

func (f *forwarder) openStream(c net.Conn, r fwdRule) {
	tuneSocket(c, f.cfg)
	l := f.p.pick()
	if l == nil {
		logWarn("no carrier up, dropping connection to :%d", r.lport)
		c.Close()
		return
	}
	s := l.newStream(c)
	if !l.send(ctrlRec(cmdSYN, s.id, []byte(r.target))) {
		s.reset()
		return
	}
	go s.pumpIn(c)
	s.pumpOut(c)
}

// ---------------------------------------------------------------------------
// edge: UDP
// ---------------------------------------------------------------------------

func (f *forwarder) serveUDP(pc net.PacketConn, r fwdRule) {
	buf := make([]byte, udpReadSize)
	for {
		n, addr, err := pc.ReadFrom(buf)
		if err != nil {
			select {
			case <-f.closed:
				return
			default:
			}
			logWarn("udp read :%d: %v", r.lport, err)
			return
		}
		if n > maxRecord {
			continue
		}
		key := strconv.Itoa(r.lport) + "|" + addr.String()
		f.mu.Lock()
		s := f.edge[key]
		if s == nil {
			l := f.p.pickHash(hash5([]byte(key)))
			if l == nil {
				f.mu.Unlock()
				continue
			}
			id := (atomic.AddUint32(&f.udpSq, 1) & 0x7fffffff) | udpIDBit
			s = &udpSess{l: l, id: id, pc: pc, cli: addr, key: key}
			f.edge[key] = s
			f.byID[sessKey{l, id}] = s
			f.mu.Unlock()
			l.send(ctrlRec(cmdUSYN, id, []byte(r.target)))
		} else {
			f.mu.Unlock()
		}
		atomic.StoreInt64(&s.last, time.Now().UnixNano())
		if !s.l.alive() {
			f.dropUDP(s)
			continue
		}
		atomic.AddUint64(&s.l.txBytes, uint64(n))
		s.l.send(ctrlRec(cmdUDP, s.id, buf[:n]))
	}
}

// ---------------------------------------------------------------------------
// origin: incoming records
// ---------------------------------------------------------------------------

func (f *forwarder) onRecord(l *link, cmd byte, id uint32, body []byte) {
	switch cmd {
	case cmdSYN:
		// Register before dialling: the data records for this stream are
		// usually already in flight behind the SYN.
		s := l.acceptStream(id, nil)
		if s == nil {
			return
		}
		go f.dialTCP(s, string(body))
	case cmdUSYN:
		f.openUDP(l, id, string(body))
	case cmdUDP:
		f.mu.Lock()
		s := f.byID[sessKey{l, id}]
		f.mu.Unlock()
		if s == nil {
			return
		}
		atomic.StoreInt64(&s.last, time.Now().UnixNano())
		atomic.AddUint64(&l.rxBytes, uint64(len(body)))
		if s.pc != nil {
			s.pc.WriteTo(body, s.cli) // edge -> the user
		} else {
			s.deliver(body) // origin -> the real service
		}
	case cmdUFIN:
		f.mu.Lock()
		s := f.byID[sessKey{l, id}]
		f.mu.Unlock()
		if s != nil {
			f.dropUDP(s)
		}
	}
}

func (f *forwarder) targetAllowed(target string) bool {
	if f.allow == nil {
		return true
	}
	return f.allow[target]
}

func (f *forwarder) dialTCP(s *stream, target string) {
	refuse := func(why string) {
		logWarn("stream to %s: %s", target, why)
		s.l.send(ctrlRec(cmdRST, s.id, nil))
		s.reset()
	}
	if !f.targetAllowed(target) {
		refuse("not in allow list")
		return
	}
	c, err := net.DialTimeout("tcp", target, time.Duration(f.cfg.DialTimeout)*time.Second)
	if err != nil {
		refuse(err.Error())
		return
	}
	tuneSocket(c, f.cfg)
	if !s.attach(c) {
		c.Close()
		return
	}
	go s.pumpIn(c)
	s.pumpOut(c)
}

// openUDP registers the session immediately - so datagrams following the USYN
// find it - and dials in the background.
func (f *forwarder) openUDP(l *link, id uint32, target string) {
	if !f.targetAllowed(target) {
		l.send(ctrlRec(cmdUFIN, id, nil))
		return
	}
	s := &udpSess{l: l, id: id}
	atomic.StoreInt64(&s.last, time.Now().UnixNano())
	f.mu.Lock()
	if old := f.byID[sessKey{l, id}]; old != nil {
		f.mu.Unlock()
		return
	}
	f.byID[sessKey{l, id}] = s
	f.mu.Unlock()

	go func() {
		ua, err := net.ResolveUDPAddr("udp", target)
		if err != nil {
			logWarn("resolve udp %s: %v", target, err)
			f.dropUDP(s)
			return
		}
		uc, err := net.DialUDP("udp", nil, ua)
		if err != nil {
			logWarn("dial udp %s: %v", target, err)
			f.dropUDP(s)
			return
		}
		s.ready(uc)

		buf := make([]byte, udpReadSize)
		for {
			uc.SetReadDeadline(time.Now().Add(udpIdleSec * time.Second))
			n, err := uc.Read(buf)
			if n > 0 && n <= maxRecord {
				atomic.StoreInt64(&s.last, time.Now().UnixNano())
				atomic.AddUint64(&l.txBytes, uint64(n))
				if !l.send(ctrlRec(cmdUDP, id, buf[:n])) {
					break
				}
			}
			if err != nil {
				break
			}
		}
		f.dropUDP(s)
	}()
}

func (f *forwarder) dropUDP(s *udpSess) {
	f.mu.Lock()
	if f.byID[sessKey{s.l, s.id}] != s {
		f.mu.Unlock()
		return
	}
	delete(f.byID, sessKey{s.l, s.id})
	if s.key != "" {
		delete(f.edge, s.key)
	}
	f.mu.Unlock()
	if uc := s.socket(); uc != nil {
		uc.Close()
	}
	if s.l.alive() {
		s.l.send(ctrlRec(cmdUFIN, s.id, nil))
	}
}

func (f *forwarder) reapUDP() {
	t := time.NewTicker(30 * time.Second)
	defer t.Stop()
	for {
		select {
		case <-t.C:
		case <-f.closed:
			return
		}
		cut := time.Now().Add(-udpIdleSec * time.Second).UnixNano()
		var dead []*udpSess
		f.mu.Lock()
		for _, s := range f.byID {
			if atomic.LoadInt64(&s.last) < cut || !s.l.alive() {
				dead = append(dead, s)
			}
		}
		f.mu.Unlock()
		for _, s := range dead {
			f.dropUDP(s)
		}
	}
}

func (f *forwarder) onLinkDown(l *link) {
	var dead []*udpSess
	f.mu.Lock()
	for k, s := range f.byID {
		if k.l == l {
			dead = append(dead, s)
		}
	}
	f.mu.Unlock()
	for _, s := range dead {
		f.dropUDP(s)
	}
}

func (f *forwarder) Close() error {
	f.once.Do(func() {
		close(f.closed)
		for _, ln := range f.listeners {
			ln.Close()
		}
		for _, pc := range f.packets {
			pc.Close()
		}
	})
	return nil
}

// ==========================================================================
// 7. tun mode - layer 3
// ==========================================================================

// tun mode carries whole IP packets instead of individual TCP connections.
// It is the right choice when the far side must be reachable as a machine
// (routing, ICMP, any protocol) rather than as a list of ports.

type tunnel struct {
	cfg    *Config
	p      *pool
	queues []*os.File
	wrIdx  uint32
	closed chan struct{}
	once   sync.Once
}

func startTUN(cfg *Config, p *pool) (*tunnel, error) {
	t := &tunnel{cfg: cfg, p: p, closed: make(chan struct{})}
	n := cfg.Carriers
	if n < 1 {
		n = 1
	}
	if n > 8 {
		n = 8 // more queues than this stops helping and costs descriptors
	}
	for i := 0; i < n; i++ {
		f, err := openTUN(cfg.TUN.Name, n > 1)
		if err != nil {
			t.Close()
			return nil, fmt.Errorf("open %s queue %d: %v", cfg.TUN.Name, i, err)
		}
		t.queues = append(t.queues, f)
	}
	if err := configureTUN(cfg.TUN); err != nil {
		t.Close()
		return nil, err
	}
	p.setHandler(t)
	for i := range t.queues {
		go t.readQueue(t.queues[i])
	}
	logInfo("tun %s up: %s peer %s mtu %d, %d queues",
		cfg.TUN.Name, cfg.TUN.Local, cfg.TUN.Peer, cfg.TUN.MTU, len(t.queues))
	return t, nil
}

func configureTUN(c TUNConfig) error {
	run := func(args ...string) error {
		out, err := exec.Command("ip", args...).CombinedOutput()
		if err != nil {
			msg := strings.TrimSpace(string(out))
			// Re-adding an address after a restart is expected, not an error.
			if strings.Contains(msg, "File exists") {
				return nil
			}
			return fmt.Errorf("ip %s: %v: %s", strings.Join(args, " "), err, msg)
		}
		return nil
	}
	if err := run("link", "set", "dev", c.Name, "mtu", fmt.Sprint(c.MTU), "up"); err != nil {
		return err
	}
	if c.Local != "" {
		if c.Peer != "" {
			if err := run("addr", "add", c.Local, "peer", c.Peer, "dev", c.Name); err != nil {
				return err
			}
		} else if err := run("addr", "add", c.Local, "dev", c.Name); err != nil {
			return err
		}
	}
	return nil
}

func (t *tunnel) readQueue(f *os.File) {
	for {
		r := getRec()
		n, err := f.Read(r.body())
		if n > 0 {
			r.seal(cmdTUN, 0, n)
			l := t.p.pickHash(flowHash(r.body()[:n]))
			if l == nil {
				putRec(r)
			} else {
				atomic.AddUint64(&l.txBytes, uint64(n))
				l.send(r)
			}
		} else {
			putRec(r)
		}
		if err != nil {
			select {
			case <-t.closed:
			default:
				logWarn("tun read: %v", err)
			}
			return
		}
	}
}

func (t *tunnel) onRecord(l *link, cmd byte, id uint32, body []byte) {
	if cmd != cmdTUN || len(t.queues) == 0 {
		return
	}
	atomic.AddUint64(&l.rxBytes, uint64(len(body)))
	q := t.queues[int(atomic.AddUint32(&t.wrIdx, 1))%len(t.queues)]
	if _, err := q.Write(body); err != nil {
		logDebug("tun write: %v", err)
	}
}

func (t *tunnel) onLinkDown(*link) {}

func (t *tunnel) Close() error {
	t.once.Do(func() {
		close(t.closed)
		for _, f := range t.queues {
			f.Close()
		}
	})
	return nil
}

// flowHash folds the 5-tuple of an IP packet into one number. Every packet of
// a given inner connection lands on the same carrier, so the inner TCP never
// sees the reordering that unequal carrier latency would otherwise create.
func flowHash(pkt []byte) uint32 {
	h := uint32(2166136261)
	mix := func(b []byte) {
		for _, c := range b {
			h ^= uint32(c)
			h *= 16777619
		}
	}
	if len(pkt) < 20 {
		return 0
	}
	switch pkt[0] >> 4 {
	case 4:
		ihl := int(pkt[0]&0x0f) * 4
		if ihl < 20 || len(pkt) < ihl {
			return 0
		}
		mix(pkt[12:20]) // src + dst
		proto := pkt[9]
		mix([]byte{proto})
		if (proto == 6 || proto == 17) && len(pkt) >= ihl+4 {
			mix(pkt[ihl : ihl+4]) // src + dst port
		}
	case 6:
		if len(pkt) < 40 {
			return 0
		}
		mix(pkt[8:40])
		nh := pkt[6]
		mix([]byte{nh})
		if (nh == 6 || nh == 17) && len(pkt) >= 44 {
			mix(pkt[40:44])
		}
	}
	return h
}

// ==========================================================================
// 8. socket tuning and forward specs
// ==========================================================================

// tuneSocket applies the settings that actually move the needle on a
// long-haul, lossy Iran<->Kharej path: no Nagle delay on the carrier, and
// socket buffers big enough to hold a full bandwidth-delay product.
func tuneSocket(c net.Conn, cfg *Config) {
	tc, ok := c.(*net.TCPConn)
	if !ok {
		return
	}
	tc.SetNoDelay(true)
	tc.SetKeepAlive(true)
	tc.SetKeepAlivePeriod(30e9)
	if cfg.SndBufKB > 0 {
		tc.SetWriteBuffer(cfg.SndBufKB * 1024)
	}
	if cfg.RcvBufKB > 0 {
		tc.SetReadBuffer(cfg.RcvBufKB * 1024)
	}
}

// ---------------------------------------------------------------------------
// forward specs
//
//	443                      tcp :443        -> 127.0.0.1:443
//	443=8443                 tcp :443        -> 127.0.0.1:8443
//	443=10.0.0.5:8443        tcp :443        -> 10.0.0.5:8443
//	8000-8010                tcp :8000..8010 -> 127.0.0.1:same
//	8000-8010=9000           tcp :8000..8010 -> 127.0.0.1:9000..9010
//	udp:500=500              udp :500        -> 127.0.0.1:500
// ---------------------------------------------------------------------------

type fwdRule struct {
	proto  string // "tcp" or "udp"
	lport  int
	target string // "host:port"
}

func parseForward(spec string) ([]fwdRule, error) {
	s := strings.TrimSpace(spec)
	if s == "" {
		return nil, fmt.Errorf("empty forward")
	}
	proto := "tcp"
	if i := strings.Index(s, ":"); i >= 0 {
		switch strings.ToLower(s[:i]) {
		case "tcp":
			proto, s = "tcp", s[i+1:]
		case "udp":
			proto, s = "udp", s[i+1:]
		}
	}

	local, remote := s, ""
	if i := strings.Index(s, "="); i >= 0 {
		local, remote = s[:i], s[i+1:]
	}

	lo, hi, err := parsePortRange(local)
	if err != nil {
		return nil, fmt.Errorf("%q: %v", spec, err)
	}

	host := "127.0.0.1"
	rbase := 0
	if remote != "" {
		rp := remote
		if i := strings.LastIndex(remote, ":"); i >= 0 {
			host, rp = remote[:i], remote[i+1:]
			if host == "" {
				host = "127.0.0.1"
			}
		}
		if rp != "" {
			rbase, err = strconv.Atoi(rp)
			if err != nil || rbase < 1 || rbase > 65535 {
				return nil, fmt.Errorf("%q: bad target port %q", spec, rp)
			}
		}
	}

	out := make([]fwdRule, 0, hi-lo+1)
	for pt := lo; pt <= hi; pt++ {
		rp := pt
		if rbase > 0 {
			rp = rbase + (pt - lo)
			if rp > 65535 {
				return nil, fmt.Errorf("%q: target port range overflows", spec)
			}
		}
		out = append(out, fwdRule{
			proto:  proto,
			lport:  pt,
			target: net.JoinHostPort(host, strconv.Itoa(rp)),
		})
	}
	return out, nil
}

func parsePortRange(s string) (int, int, error) {
	if i := strings.Index(s, "-"); i >= 0 {
		lo, e1 := strconv.Atoi(strings.TrimSpace(s[:i]))
		hi, e2 := strconv.Atoi(strings.TrimSpace(s[i+1:]))
		if e1 != nil || e2 != nil || lo < 1 || hi > 65535 || lo > hi {
			return 0, 0, fmt.Errorf("bad port range %q", s)
		}
		if hi-lo > 512 {
			return 0, 0, fmt.Errorf("port range %q is wider than 512 ports", s)
		}
		return lo, hi, nil
	}
	p, err := strconv.Atoi(strings.TrimSpace(s))
	if err != nil || p < 1 || p > 65535 {
		return 0, 0, fmt.Errorf("bad port %q", s)
	}
	return p, p, nil
}

// hash5 is a FNV-1a over the fields that identify one inner flow. It is what
// keeps a flow glued to a single carrier.
func hash5(b []byte) uint32 {
	h := uint32(2166136261)
	for _, c := range b {
		h ^= uint32(c)
		h *= 16777619
	}
	return h
}

// ==========================================================================
// 9. status endpoint
// ==========================================================================

// A tiny loopback-only status endpoint. The manager script reads it for the
// health check, so the check reflects what the engine actually sees rather
// than merely whether the process exists.

type carrierStatus struct {
	Index   int     `json:"index"`
	Up      bool    `json:"up"`
	Streams int     `json:"streams"`
	TxBytes uint64  `json:"tx_bytes"`
	RxBytes uint64  `json:"rx_bytes"`
	RTTms   float64 `json:"rtt_ms"`
	UptimeS int64   `json:"uptime_s"`
}

type statusDoc struct {
	Name      string          `json:"name"`
	Version   string          `json:"version"`
	Role      string          `json:"role"`
	Mode      string          `json:"mode"`
	Transport string          `json:"transport"`
	Peer      string          `json:"peer"`
	Healthy   bool            `json:"healthy"`
	Carriers  int             `json:"carriers_configured"`
	Up        int             `json:"carriers_up"`
	Streams   int             `json:"streams"`
	TxBytes   uint64          `json:"tx_bytes"`
	RxBytes   uint64          `json:"rx_bytes"`
	RTTms     float64         `json:"rtt_ms"`
	UptimeS   int64           `json:"uptime_s"`
	Detail    []carrierStatus `json:"detail"`
}

func startStatusServer(addr string, cfg *Config, p *pool) {
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		logWarn("status endpoint %s: %v", addr, err)
		return
	}
	mux := http.NewServeMux()
	mux.HandleFunc("/status", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(snapshot(cfg, p))
	})
	mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
		if snapshot(cfg, p).Healthy {
			w.WriteHeader(http.StatusOK)
			w.Write([]byte("ok\n"))
			return
		}
		w.WriteHeader(http.StatusServiceUnavailable)
		w.Write([]byte("no carrier\n"))
	})
	srv := &http.Server{Handler: mux, ReadHeaderTimeout: 5 * time.Second}
	go srv.Serve(ln)
	logInfo("status endpoint on http://%s/status", addr)
}

func snapshot(cfg *Config, p *pool) statusDoc {
	d := statusDoc{
		Name:      cfg.Name,
		Version:   version,
		Role:      cfg.Role,
		Mode:      cfg.Mode,
		Transport: cfg.Transport,
		Peer:      cfg.Connect,
		Carriers:  cfg.Carriers,
		UptimeS:   int64(time.Since(p.startedAt).Seconds()),
	}
	if d.Peer == "" {
		d.Peer = "listen " + cfg.Listen
	}
	now := time.Now().UnixNano()
	for _, l := range p.liveLinks() {
		cs := carrierStatus{
			Index:   l.idx,
			Up:      l.alive(),
			Streams: l.streamCount(),
			TxBytes: atomic.LoadUint64(&l.txBytes),
			RxBytes: atomic.LoadUint64(&l.rxBytes),
			RTTms:   float64(atomic.LoadInt64(&l.rttUS)) / 1000,
			UptimeS: (now - atomic.LoadInt64(&l.upSince)) / int64(time.Second),
		}
		if cs.Up {
			d.Up++
			d.Streams += cs.Streams
			if cs.RTTms > d.RTTms {
				d.RTTms = cs.RTTms
			}
		}
		d.TxBytes += cs.TxBytes
		d.RxBytes += cs.RxBytes
		d.Detail = append(d.Detail, cs)
	}
	d.Healthy = d.Up > 0
	return d
}

// ---------------------------------------------------------------------------
// client side of the status endpoint: keeps the manager script free of any
// JSON tooling, so it needs nothing beyond bash and systemd.
// ---------------------------------------------------------------------------

func fetchStatus(addr string) (*statusDoc, error) {
	c := &http.Client{Timeout: 3 * time.Second}
	resp, err := c.Get("http://" + addr + "/status")
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	var d statusDoc
	if err := json.NewDecoder(resp.Body).Decode(&d); err != nil {
		return nil, err
	}
	if !d.Healthy {
		return &d, fmt.Errorf("no carrier is up")
	}
	return &d, nil
}

func humanBytes(n uint64) string {
	const unit = 1024
	if n < unit {
		return fmt.Sprintf("%d B", n)
	}
	div, exp := uint64(unit), 0
	for v := n / unit; v >= unit && exp < 4; v /= unit {
		div *= unit
		exp++
	}
	return fmt.Sprintf("%.1f %ciB", float64(n)/float64(div), "KMGTP"[exp])
}

func humanDuration(sec int64) string {
	d := time.Duration(sec) * time.Second
	switch {
	case d >= 24*time.Hour:
		return fmt.Sprintf("%dd %dh", sec/86400, (sec%86400)/3600)
	case d >= time.Hour:
		return fmt.Sprintf("%dh %dm", sec/3600, (sec%3600)/60)
	case d >= time.Minute:
		return fmt.Sprintf("%dm %ds", sec/60, sec%60)
	}
	return fmt.Sprintf("%ds", sec)
}

// printStatus renders the status endpoint. It returns the process exit code so
// that scripts can branch on tunnel health without parsing anything.
func printStatus(addr string, brief bool) int {
	d, err := fetchStatus(addr)
	if d == nil {
		if brief {
			fmt.Println("down 0 0 0.0 0 0")
		} else {
			fmt.Printf("unreachable: %v\n", err)
		}
		return 1
	}
	if brief {
		state := "down"
		if d.Healthy {
			state = "up"
		}
		// state carriers_up carriers_total rtt_ms streams uptime_s
		fmt.Printf("%s %d %d %.1f %d %d\n", state, d.Up, d.Carriers, d.RTTms, d.Streams, d.UptimeS)
		if d.Healthy {
			return 0
		}
		return 1
	}

	state := "DOWN"
	if d.Healthy {
		state = "UP"
	}
	fmt.Printf("  tunnel     %s  (%s, %s, %s)\n", d.Name, d.Role, d.Mode, d.Transport)
	fmt.Printf("  state      %s  -  %d of %d carriers\n", state, d.Up, d.Carriers)
	fmt.Printf("  peer       %s\n", d.Peer)
	fmt.Printf("  rtt        %.1f ms\n", d.RTTms)
	fmt.Printf("  streams    %d open\n", d.Streams)
	fmt.Printf("  traffic    tx %s / rx %s\n", humanBytes(d.TxBytes), humanBytes(d.RxBytes))
	fmt.Printf("  uptime     %s\n", humanDuration(d.UptimeS))
	if len(d.Detail) > 0 {
		fmt.Printf("\n  %-4s %-6s %-8s %-9s %-12s %-12s\n", "#", "state", "streams", "rtt", "tx", "rx")
		for _, c := range d.Detail {
			cs := "down"
			if c.Up {
				cs = "up"
			}
			fmt.Printf("  %-4d %-6s %-8d %-9s %-12s %-12s\n",
				c.Index, cs, c.Streams, fmt.Sprintf("%.1f ms", c.RTTms),
				humanBytes(c.TxBytes), humanBytes(c.RxBytes))
		}
	}
	if d.Healthy {
		return 0
	}
	return 1
}
PINGIFY_SRC_EOF
    cat > "$d/tun_linux.go" <<'PINGIFY_SRC_EOF'
//go:build linux

package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

// TUN flags and the TUNSETIFF ioctl, copied from <linux/if_tun.h> so the
// engine needs no cgo and no third-party package.
const (
	iffTUN         = 0x0001
	iffNoPI        = 0x1000
	iffMultiQueue  = 0x0100
	ioctlTUNSETIFF = 0x400454ca
)

type ifReq struct {
	name  [16]byte
	flags uint16
	_     [22]byte
}

// openTUN attaches one queue to the named interface, creating it on first use.
// With multiqueue set, calling it again for the same name adds another queue,
// which lets several goroutines read the device without fighting for a lock.
func openTUN(name string, multiqueue bool) (*os.File, error) {
	if len(name) >= 16 {
		return nil, fmt.Errorf("interface name %q is too long", name)
	}
	fd, err := syscall.Open("/dev/net/tun", syscall.O_RDWR, 0)
	if err != nil {
		return nil, fmt.Errorf("/dev/net/tun: %v (is the tun module loaded?)", err)
	}
	var req ifReq
	copy(req.name[:], name)
	req.flags = iffTUN | iffNoPI
	if multiqueue {
		req.flags |= iffMultiQueue
	}
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd),
		uintptr(ioctlTUNSETIFF), uintptr(unsafe.Pointer(&req))); errno != 0 {
		syscall.Close(fd)
		return nil, fmt.Errorf("TUNSETIFF %s: %v", name, errno)
	}
	return os.NewFile(uintptr(fd), "/dev/net/tun"), nil
}
PINGIFY_SRC_EOF
    cat > "$d/tun_other.go" <<'PINGIFY_SRC_EOF'
//go:build !linux

package main

import (
	"errors"
	"os"
)

// Kept so the package still compiles (and its tests still run) on a developer
// machine that is not Linux. tun mode itself is Linux-only by nature.
func openTUN(name string, multiqueue bool) (*os.File, error) {
	return nil, errors.New("tun mode is only available on Linux")
}
PINGIFY_SRC_EOF
